-- Faits retravaillés.
WITH fact_seed (
  category_slug,
  slug,
  title,
  hook,
  content,
  long_content,
  source,
  source_url,
  display_order,
  accent_color,
  tone
) AS (
  VALUES
  ($q$histoire-essentielle$q$, $q$la-premiere-guerre-mondiale-a-commence-en-1914$q$, $q$La Première Guerre mondiale a commencé en 1914.$q$, $q$Un conflit pensé court a bouleversé durablement l’Europe.$q$, $q$À l’été 1914, beaucoup pensent encore que la guerre sera rapide. Elle dure finalement plus de quatre ans, mobilise des millions de soldats et transforme les frontières, les sociétés et la manière de voir la guerre.$q$, $q$La Première Guerre mondiale commence après l’assassinat de l’archiduc François-Ferdinand à Sarajevo, mais ses causes sont plus profondes : alliances militaires, rivalités impériales et tensions nationalistes. Le conflit s’étend rapidement à une grande partie de l’Europe puis au monde. Les tranchées, les armes industrielles et les pertes humaines massives marquent les esprits. En 1918, l’Europe sort affaiblie, redessinée et profondément traumatisée. Comprendre 1914 aide à comprendre tout le XXe siècle.$q$, $q$Encyclopaedia Britannica$q$, $q$https://www.britannica.com/event/World-War-I$q$, 1, $q$#f97316$q$, $q$from-[#1c1917] via-[#7c2d12] to-[#fb923c]$q$),
  ($q$histoire-essentielle$q$, $q$la-revolution-francaise-a-commence-en-1789$q$, $q$La Révolution française a commencé en 1789.$q$, $q$1789 marque le moment où l’ordre politique français bascule.$q$, $q$Cette année-là, la contestation contre la monarchie devient un bouleversement politique majeur. La prise de la Bastille, le 14 juillet, devient l’un des symboles les plus connus de cette période.$q$, $q$En 1789, la France traverse une crise financière, sociale et politique. Les privilèges de la noblesse et du clergé sont de plus en plus contestés, tandis qu’une partie de la population réclame davantage de représentation. La prise de la Bastille n’est pas seulement une attaque contre une prison : elle devient le symbole de la chute de l’autorité royale. La Révolution entraînera ensuite la fin de l’Ancien Régime, la Déclaration des droits de l’homme et une transformation profonde de la société française.$q$, $q$Encyclopaedia Britannica$q$, $q$https://www.britannica.com/event/French-Revolution$q$, 2, $q$#f97316$q$, $q$from-[#1c1917] via-[#7c2d12] to-[#fb923c]$q$),
  ($q$histoire-essentielle$q$, $q$le-premier-pas-sur-la-lune-a-eu-lieu-en-1969$q$, $q$Le premier pas sur la Lune a eu lieu en 1969.$q$, $q$1969 devient l’année où l’humain marche sur un autre monde.$q$, $q$Neil Armstrong pose le pied sur la Lune lors de la mission Apollo 11. Des centaines de millions de personnes suivent l’événement à la télévision, à une époque où cela paraît encore presque irréel.$q$, $q$Apollo 11 est l’aboutissement de la course à l’espace entre les États-Unis et l’URSS pendant la guerre froide. Le 20 juillet 1969, Neil Armstrong et Buzz Aldrin se posent sur la Lune pendant que Michael Collins reste en orbite. L’événement est scientifique, mais aussi politique et symbolique. Il montre la puissance technologique américaine et nourrit l’imaginaire collectif autour de l’exploration spatiale. Aujourd’hui encore, cette date reste l’un des grands repères du XXe siècle.$q$, $q$NASA$q$, $q$https://www.nasa.gov/mission/apollo-11/$q$, 3, $q$#f97316$q$, $q$from-[#1c1917] via-[#7c2d12] to-[#fb923c]$q$),
  ($q$histoire-essentielle$q$, $q$le-mur-de-berlin-est-tombe-en-1989$q$, $q$Le mur de Berlin est tombé en 1989.$q$, $q$La chute du Mur symbolise la fin de la division de l’Europe.$q$, $q$Construit pendant la guerre froide, il séparait Berlin-Est et Berlin-Ouest depuis 1961. Sa chute devient l’une des images les plus fortes de la fin du bloc soviétique en Europe.$q$, $q$Le mur de Berlin est construit par l’Allemagne de l’Est pour empêcher ses habitants de fuir vers Berlin-Ouest. Pendant près de trente ans, il sépare familles, amis et quartiers entiers. Il devient le symbole concret de la guerre froide : d’un côté le bloc soviétique, de l’autre l’Ouest. En 1989, sous la pression populaire et l’affaiblissement du régime est-allemand, les frontières s’ouvrent. Les images de la foule détruisant le Mur marquent la fin d’une époque et annoncent la réunification allemande.$q$, $q$Encyclopaedia Britannica$q$, $q$https://www.britannica.com/topic/Berlin-Wall$q$, 4, $q$#f97316$q$, $q$from-[#1c1917] via-[#7c2d12] to-[#fb923c]$q$),
  ($q$histoire-essentielle$q$, $q$christophe-colomb-atteint-lamerique-en-1492$q$, $q$Christophe Colomb atteint l’Amérique en 1492.$q$, $q$Colomb pense rejoindre l’Asie, mais ouvre une nouvelle période historique.$q$, $q$En traversant l’Atlantique, Christophe Colomb ne croit pas découvrir un nouveau continent. Son voyage devient pourtant, dans l’histoire européenne, le point de départ des grandes explorations vers les Amériques.$q$, $q$En 1492, Christophe Colomb part pour trouver une route maritime vers l’Asie en naviguant vers l’ouest. Il atteint les Caraïbes, sans comprendre qu’il se trouve face à un continent encore inconnu des Européens. Cette arrivée ouvre une période d’explorations, de conquêtes et de colonisation qui transformera profondément les Amériques, l’Europe et le commerce mondial. C’est une date essentielle, mais aussi liée à des conséquences violentes pour les populations autochtones.$q$, $q$Encyclopaedia Britannica$q$, $q$https://www.britannica.com/biography/Christopher-Columbus$q$, 5, $q$#f97316$q$, $q$from-[#1c1917] via-[#7c2d12] to-[#fb923c]$q$),
  ($q$histoire-essentielle$q$, $q$gutenberg-rend-les-livres-beaucoup-plus-faciles-a-copier$q$, $q$Gutenberg a rendu les livres beaucoup plus faciles à copier.$q$, $q$Avant l’imprimerie, produire un livre demandait un travail immense.$q$, $q$Au XVe siècle, Gutenberg utilise des caractères mobiles : des lettres réutilisables que l’on assemble pour imprimer des pages. Cela rend les livres plus nombreux, moins chers et aide les idées à circuler plus vite.$q$, $q$Avant Gutenberg, beaucoup de livres sont copiés à la main, ce qui demande énormément de temps et les rend rares. Son imprimerie ne crée pas le savoir, mais accélère sa diffusion. Les caractères mobiles permettent de recomposer des pages et de produire plusieurs exemplaires plus rapidement. Cette innovation favorise la circulation des textes religieux, scientifiques et politiques. Elle joue un rôle majeur dans la Renaissance, la Réforme et l’essor de la lecture en Europe.$q$, $q$Encyclopaedia Britannica$q$, $q$https://www.britannica.com/technology/printing-press$q$, 6, $q$#f97316$q$, $q$from-[#1c1917] via-[#7c2d12] to-[#fb923c]$q$),
  ($q$histoire-essentielle$q$, $q$la-guerre-froide-netait-pas-une-guerre-classique$q$, $q$La guerre froide n’était pas une guerre classique.$q$, $q$Deux superpuissances s’affrontent surtout sans bataille directe.$q$, $q$Les États-Unis et l’URSS ne se livrent pas une grande guerre frontale. Leur rivalité passe plutôt par l’espionnage, la propagande, la course à l’espace, l’arme nucléaire et des conflits indirects.$q$, $q$Après 1945, les États-Unis et l’URSS deviennent les deux grandes puissances rivales. Chacun défend un modèle politique et économique opposé. Comme une guerre directe pourrait devenir nucléaire, l’affrontement se déplace vers d’autres terrains : influence diplomatique, compétitions technologiques, guerres par alliés interposés et propagande. La guerre froide permet de comprendre la course à l’espace, le mur de Berlin, la crise de Cuba et plusieurs conflits du XXe siècle.$q$, $q$Encyclopaedia Britannica$q$, $q$https://www.britannica.com/event/Cold-War$q$, 7, $q$#f97316$q$, $q$from-[#1c1917] via-[#7c2d12] to-[#fb923c]$q$),
  ($q$histoire-essentielle$q$, $q$la-peste-noire-a-frappe-leurope-au-xive-siecle$q$, $q$La peste noire a frappé l’Europe au XIVe siècle.$q$, $q$L’épidémie change la société autant que la santé.$q$, $q$Entre 1347 et 1351, la peste noire tue une part immense de la population européenne. Elle bouleverse le rapport à la mort, au travail, à la religion et à l’organisation sociale.$q$, $q$La peste noire arrive en Europe au milieu du XIVe siècle et se propage très vite. Les villes, les échanges commerciaux et le manque de connaissances médicales favorisent la catastrophe. La mortalité est si forte que certaines régions manquent de travailleurs, ce qui modifie les rapports économiques. L’épidémie laisse aussi une trace profonde dans l’art, la religion et l’imaginaire collectif. C’est l’un des grands traumatismes de l’Europe médiévale.$q$, $q$Encyclopaedia Britannica$q$, $q$https://www.britannica.com/event/Black-Death$q$, 8, $q$#f97316$q$, $q$from-[#1c1917] via-[#7c2d12] to-[#fb923c]$q$),
  ($q$histoire-essentielle$q$, $q$la-declaration-des-droits-de-lhomme-date-de-1789$q$, $q$La Déclaration des droits de l’homme date de 1789.$q$, $q$Des idées banales aujourd’hui étaient alors révolutionnaires.$q$, $q$Le texte affirme des principes comme la liberté, l’égalité devant la loi et la souveraineté de la nation. Même imparfaitement appliqué, il devient une référence politique majeure.$q$, $q$La Déclaration des droits de l’homme et du citoyen est rédigée pendant la Révolution française. Elle cherche à rompre avec l’Ancien Régime, les privilèges et l’idée d’un pouvoir venu uniquement du roi. Le texte affirme que les citoyens ont des droits et que la loi doit s’appliquer à tous. À l’époque, ces idées sont puissantes et radicales. Elles influenceront durablement la politique française et de nombreuses constitutions modernes.$q$, $q$Vie publique$q$, $q$https://www.vie-publique.fr/fiches/19567-la-declaration-des-droits-de-lhomme-et-du-citoyen-de-1789$q$, 9, $q$#f97316$q$, $q$from-[#1c1917] via-[#7c2d12] to-[#fb923c]$q$),
  ($q$histoire-essentielle$q$, $q$le-11-novembre-marque-la-fin-des-combats-de-1918$q$, $q$Le 11 novembre marque la fin des combats de 1918.$q$, $q$L’armistice arrête les combats, pas toute la paix.$q$, $q$Le 11 novembre 1918, l’armistice met fin aux combats de la Première Guerre mondiale. Le traité de paix arrive plus tard, mais cette date reste associée au souvenir des soldats morts pendant la guerre.$q$, $q$Le 11 novembre 1918, l’Allemagne signe l’armistice avec les Alliés. Les combats cessent après plus de quatre années d’une guerre extrêmement meurtrière. La paix officielle sera organisée ensuite par le traité de Versailles en 1919. En France et dans plusieurs pays, le 11 novembre devient une journée de mémoire. Elle rappelle les soldats morts, les souffrances du conflit et l’importance de cette rupture dans l’histoire européenne.$q$, $q$Service public$q$, $q$https://www.service-public.fr/particuliers/actualites/A15759$q$, 10, $q$#f97316$q$, $q$from-[#1c1917] via-[#7c2d12] to-[#fb923c]$q$),
  ($q$cinema-culture-pop$q$, $q$le-premier-film-de-lhistoire-date-de-1888$q$, $q$Le premier film de l’histoire date de 1888.$q$, $q$Quelques secondes d’images animées étaient déjà un exploit.$q$, $q$C’était Roundhay Garden Scene, un très court film montrant simplement des personnes dans un jardin. À l’époque, voir des images bouger suffisait déjà à impressionner.$q$, $q$Roundhay Garden Scene est filmé au Royaume-Uni par Louis Le Prince en 1888. Le film dure moins de trois secondes, mais il marque une étape essentielle dans l’histoire des images animées. À cette époque, le cinéma n’existe pas encore comme art ou industrie. Les caméras sont expérimentales et la simple capture du mouvement fascine. Quelques années plus tard, les frères Lumière populariseront les projections publiques. Ce petit film rappelle que le cinéma mondial commence avec une scène presque banale.$q$, $q$Science Museum$q$, $q$https://www.sciencemuseum.org.uk/objects-and-stories/very-short-history-of-cinema$q$, 11, $q$#ec4899$q$, $q$from-[#1f1020] via-[#831843] to-[#f472b6]$q$),
  ($q$cinema-culture-pop$q$, $q$charlie-chaplin-est-devenu-celebre-sans-presque-parler$q$, $q$Charlie Chaplin est devenu mondialement célèbre sans presque parler.$q$, $q$Chaplin prouve qu’un personnage peut traverser les langues.$q$, $q$Acteur et réalisateur britannique du cinéma muet, Charlie Chaplin devient célèbre grâce à son personnage de Charlot. Ses gestes, son visage et sa silhouette suffisent à faire comprendre ses histoires partout dans le monde.$q$, $q$Charlie Chaplin est l’une des grandes figures du cinéma du début du XXe siècle. Son personnage de Charlot, avec son chapeau melon, sa canne et sa démarche reconnaissable, devient universel. À l’époque du cinéma muet, les acteurs doivent transmettre les émotions sans dialogue. Chaplin excelle dans cet art, mêlant humour, tendresse et critique sociale. Des films comme Les Temps modernes ou Le Kid expliquent pourquoi son nom reste une référence majeure du cinéma.$q$, $q$Encyclopaedia Britannica$q$, $q$https://www.britannica.com/biography/Charlie-Chaplin$q$, 12, $q$#ec4899$q$, $q$from-[#1f1020] via-[#831843] to-[#f472b6]$q$),
  ($q$cinema-culture-pop$q$, $q$hitchcock-est-surnomme-le-maitre-du-suspense$q$, $q$Hitchcock est surnommé le maître du suspense.$q$, $q$Chez Hitchcock, l’attente fait souvent plus peur que le choc.$q$, $q$Alfred Hitchcock était un réalisateur britannique surtout actif au milieu du XXe siècle. Il est connu pour Psychose, Fenêtre sur cour ou Sueurs froides, des films qui ont marqué la manière de créer la tension au cinéma.$q$, $q$Alfred Hitchcock est l’un des réalisateurs les plus célèbres de l’histoire du cinéma. Il ne cherchait pas seulement à surprendre, mais à installer une tension lente et psychologique. Ses films mettent souvent le spectateur dans une position inconfortable : il sait qu’un danger arrive, mais ne sait pas quand. Psychose, Fenêtre sur cour et Sueurs froides font partie de ses œuvres les plus connues. Son style a influencé durablement les thrillers et le cinéma de suspense.$q$, $q$British Film Institute$q$, $q$https://www.bfi.org.uk/features/alfred-hitchcock-where-begin$q$, 13, $q$#ec4899$q$, $q$from-[#1f1020] via-[#831843] to-[#f472b6]$q$),
  ($q$cinema-culture-pop$q$, $q$pulp-fiction-est-raconte-dans-le-desordre-volontairement$q$, $q$Pulp Fiction est raconté dans le désordre volontairement.$q$, $q$Le spectateur doit lui-même reconstruire l’histoire.$q$, $q$Sorti en 1994, le film de Quentin Tarantino mélange volontairement les moments du récit. Cette narration éclatée donne au film un style très reconnaissable et marque fortement le cinéma des années 1990.$q$, $q$Pulp Fiction ne raconte pas son histoire du début à la fin. Quentin Tarantino découpe le récit en morceaux et les présente dans un ordre inattendu. Le spectateur comprend progressivement les liens entre les personnages et les scènes. Ce procédé donne une impression de puzzle, tout en renforçant le style du film. Avec ses dialogues, sa bande-son et sa structure, Pulp Fiction devient l’un des films emblématiques des années 1990.$q$, $q$Festival de Cannes$q$, $q$https://www.festival-cannes.com/en/f/pulp-fiction/$q$, 14, $q$#ec4899$q$, $q$from-[#1f1020] via-[#831843] to-[#f472b6]$q$),
  ($q$cinema-culture-pop$q$, $q$star-wars-etait-un-projet-trop-etrange-pour-rassurer-hollywood$q$, $q$Star Wars paraissait trop étrange pour rassurer Hollywood.$q$, $q$Avant de devenir culte, Star Wars inquiétait une partie de l’industrie.$q$, $q$Dans les années 1970, le mélange de sabres laser, de robots, de vaisseaux et de mythologie semble risqué. Plusieurs personnes autour du projet doutent de son potentiel avant sa sortie en 1977.$q$, $q$Quand George Lucas développe Star Wars, la science-fiction n’est pas encore une valeur sûre pour les grands studios. Le film mélange aventure, western, conte mythologique et effets spéciaux ambitieux. Le tournage est difficile et certains ne comprennent pas vraiment l’univers proposé. Pourtant, à sa sortie, le film devient un phénomène mondial. Il transforme Hollywood, popularise les produits dérivés et impose une nouvelle manière de penser les blockbusters.$q$, $q$Lucasfilm$q$, $q$https://www.lucasfilm.com/productions/star-wars-a-new-hope/$q$, 15, $q$#ec4899$q$, $q$from-[#1f1020] via-[#831843] to-[#f472b6]$q$),
  ($q$cinema-culture-pop$q$, $q$jurassic-park-a-change-les-effets-speciaux-modernes$q$, $q$Jurassic Park a changé les effets spéciaux modernes.$q$, $q$Après Jurassic Park, les créatures numériques deviennent crédibles.$q$, $q$Sorti en 1993, le film mélange animatroniques et images numériques avec un réalisme impressionnant. Les dinosaures semblent vivants, ce qui change les attentes du public envers les effets spéciaux.$q$, $q$Avant Jurassic Park, les créatures fantastiques étaient souvent réalisées avec des maquettes, des costumes ou des effets parfois visibles. Steven Spielberg et Industrial Light & Magic combinent ici des robots très détaillés et des images de synthèse. Le résultat donne l’impression que les dinosaures peuvent vraiment exister à l’écran. Le film devient un repère technique pour Hollywood et ouvre la voie à l’usage massif du numérique dans les blockbusters.$q$, $q$Industrial Light & Magic$q$, $q$https://www.ilm.com/vfx/jurassic-park/$q$, 16, $q$#ec4899$q$, $q$from-[#1f1020] via-[#831843] to-[#f472b6]$q$),
  ($q$cinema-culture-pop$q$, $q$le-parrain-a-failli-ne-pas-avoir-marlon-brando$q$, $q$Le Parrain a failli ne pas avoir Marlon Brando.$q$, $q$Un choix contesté devient l’un des rôles les plus célèbres du cinéma.$q$, $q$Le studio doutait de Marlon Brando, jugé difficile et risqué. Son interprétation de Vito Corleone deviendra pourtant l’une des plus marquantes de l’histoire du cinéma.$q$, $q$Au début du projet, Marlon Brando n’est pas un choix évident pour le studio. Sa réputation inquiète, et son image semble loin d’un pari sûr. Francis Ford Coppola insiste pourtant pour lui donner le rôle de Vito Corleone. Brando transforme le personnage avec sa voix, sa posture et son autorité calme. Le Parrain sort en 1972 et devient rapidement un classique, souvent cité parmi les plus grands films jamais réalisés.$q$, $q$Paramount Pictures$q$, $q$https://www.paramountmovies.com/movies/the-godfather$q$, 17, $q$#ec4899$q$, $q$from-[#1f1020] via-[#831843] to-[#f472b6]$q$),
  ($q$cinema-culture-pop$q$, $q$les-dents-de-la-mer-a-invente-le-blockbuster-dete$q$, $q$Les Dents de la mer a changé la sortie des films d’été.$q$, $q$L’été devient une saison stratégique pour Hollywood.$q$, $q$Avant ce succès de 1975, l’été n’est pas forcément la grande période des sorties majeures. Les Dents de la mer montre qu’un film populaire peut devenir un événement national pendant les vacances.$q$, $q$Les Dents de la mer, réalisé par Steven Spielberg, sort avec une stratégie de diffusion très large et une forte campagne marketing. Le film attire massivement le public et transforme la manière dont les studios pensent leurs sorties. Il prouve qu’un film de divertissement peut dominer l’été et rapporter énormément. Avec Star Wars, il contribue à installer la logique du blockbuster moderne : lancement massif, événement médiatique et forte présence dans la culture populaire.$q$, $q$Universal Pictures$q$, $q$https://www.universalpictures.com/movies/jaws$q$, 18, $q$#ec4899$q$, $q$from-[#1f1020] via-[#831843] to-[#f472b6]$q$),
  ($q$cinema-culture-pop$q$, $q$toy-story-est-le-premier-long-metrage-entierement-en-images-de-synthese$q$, $q$Toy Story est le premier long-métrage entièrement en images de synthèse.$q$, $q$Un film de jouets ouvre une nouvelle époque de l’animation.$q$, $q$Sorti en 1995, Toy Story prouve qu’un film animé entièrement par ordinateur peut toucher le grand public. Après lui, l’animation numérique devient progressivement centrale au cinéma.$q$, $q$Toy Story est produit par Pixar et distribué par Disney. Le film part d’une idée très simple : les jouets prennent vie quand les humains quittent la pièce. Derrière cette simplicité, il marque une révolution technique. Pour la première fois, un long-métrage entier est créé en images de synthèse. Son succès montre que la technologie peut servir une histoire chaleureuse et accessible. Il ouvre une nouvelle période pour l’animation mondiale.$q$, $q$Pixar$q$, $q$https://www.pixar.com/feature-films/toy-story$q$, 19, $q$#ec4899$q$, $q$from-[#1f1020] via-[#831843] to-[#f472b6]$q$),
  ($q$cinema-culture-pop$q$, $q$le-cinema-muet-netait-pas-vraiment-silencieux$q$, $q$Le cinéma muet n’était pas vraiment silencieux.$q$, $q$Les films muets avaient souvent une musique en salle.$q$, $q$Même sans dialogues enregistrés, les projections étaient souvent accompagnées par un pianiste, un orchestre ou des effets sonores. Le public ne regardait donc pas les films dans un silence total.$q$, $q$Le terme “cinéma muet” peut donner une fausse impression. Les films n’avaient pas de voix synchronisées, mais les séances étaient souvent très vivantes. Des musiciens accompagnaient les images pour créer de l’émotion, du rythme ou de la tension. Certaines grandes salles utilisaient même des orchestres. Cette tradition explique pourquoi la musique reste encore aujourd’hui essentielle au cinéma.$q$, $q$Library of Congress$q$, $q$https://www.loc.gov/collections/silent-film-sheet-music/about-this-collection/$q$, 20, $q$#ec4899$q$, $q$from-[#1f1020] via-[#831843] to-[#f472b6]$q$),
  ($q$grandes-figures$q$, $q$einstein-a-change-notre-maniere-de-penser-le-temps-et-lespace$q$, $q$Einstein a changé notre manière de penser le temps et l’espace.$q$, $q$Même sans comprendre ses équations, on peut retenir son impact.$q$, $q$Albert Einstein était un physicien du XXe siècle. Il est surtout connu pour la relativité, une théorie qui bouleverse notre façon de comprendre le temps, l’espace, la gravité et l’univers.$q$, $q$Einstein n’est pas seulement devenu célèbre parce qu’il était considéré comme un génie. Ses travaux ont changé les bases de la physique moderne. La relativité montre notamment que le temps et l’espace ne sont pas aussi fixes qu’on l’imaginait. Ses idées ont influencé la cosmologie, l’énergie nucléaire, le GPS et notre manière de penser l’univers. Son image est devenue un symbole culturel de l’intelligence scientifique.$q$, $q$Nobel Prize$q$, $q$https://www.nobelprize.org/prizes/physics/1921/einstein/facts/$q$, 21, $q$#8b5cf6$q$, $q$from-[#17132a] via-[#4c1d95] to-[#a78bfa]$q$),
  ($q$grandes-figures$q$, $q$napoleon-netait-probablement-pas-si-petit$q$, $q$Napoléon n’était probablement pas si petit.$q$, $q$La petite taille de Napoléon est surtout une légende.$q$, $q$Napoléon Bonaparte, empereur français du début du XIXe siècle, est souvent représenté comme très petit. En réalité, sa taille était plutôt normale pour son époque, et sa réputation vient en partie de caricatures et de confusions de mesures.$q$, $q$Napoléon est l’une des figures les plus connues de l’histoire française, à la fois général, chef d’État et empereur. L’image d’un homme minuscule vient beaucoup de la propagande britannique, qui aimait le ridiculiser. Des différences entre mesures françaises et anglaises ont aussi entretenu la confusion. Retenir cela est intéressant car cela montre comment une caricature politique peut devenir une croyance populaire durable.$q$, $q$Fondation Napoléon$q$, $q$https://www.napoleon.org/$q$, 22, $q$#8b5cf6$q$, $q$from-[#17132a] via-[#4c1d95] to-[#a78bfa]$q$),
  ($q$grandes-figures$q$, $q$marie-curie-a-recu-deux-prix-nobel$q$, $q$Marie Curie a reçu deux prix Nobel.$q$, $q$Marie Curie reste une exception dans l’histoire des sciences.$q$, $q$Physicienne et chimiste, Marie Curie reçoit un prix Nobel de physique puis un prix Nobel de chimie. Son nom reste associé à la radioactivité et à la place des femmes dans l’histoire scientifique.$q$, $q$Marie Curie travaille avec Pierre Curie sur la radioactivité, un domaine alors nouveau. Elle devient la première femme à recevoir un prix Nobel, puis l’une des rares personnes à en recevoir deux dans deux disciplines scientifiques différentes. Son parcours est d’autant plus marquant qu’elle évolue dans un milieu scientifique très masculin. Elle reste une figure centrale de la science moderne et de la reconnaissance des femmes chercheuses.$q$, $q$Nobel Prize$q$, $q$https://www.nobelprize.org/prizes/physics/1903/marie-curie/facts/$q$, 23, $q$#8b5cf6$q$, $q$from-[#17132a] via-[#4c1d95] to-[#a78bfa]$q$),
  ($q$grandes-figures$q$, $q$martin-luther-king-est-devenu-le-visage-des-droits-civiques$q$, $q$Martin Luther King est devenu le visage du combat pour les droits civiques.$q$, $q$Un discours a résumé une lutte entière pour l’égalité.$q$, $q$Pasteur américain et militant non violent, Martin Luther King lutte contre la ségrégation raciale aux États-Unis. Son discours I Have a Dream reste l’un des plus célèbres du XXe siècle.$q$, $q$Martin Luther King devient une figure majeure du mouvement américain des droits civiques dans les années 1950 et 1960. Il défend la désobéissance civile non violente pour lutter contre les lois racistes. Son discours de 1963 à Washington transforme une revendication politique en image simple : celle d’un avenir où les enfants ne seraient plus jugés par leur couleur de peau. Il est assassiné en 1968, mais son influence reste immense.$q$, $q$The King Center$q$, $q$https://thekingcenter.org/about-tkc/martin-luther-king-jr/$q$, 24, $q$#8b5cf6$q$, $q$from-[#17132a] via-[#4c1d95] to-[#a78bfa]$q$),
  ($q$grandes-figures$q$, $q$cleopatre-etait-plus-proche-de-nous-que-des-pyramides$q$, $q$Cléopâtre était plus proche de nous que des pyramides.$q$, $q$Les pyramides étaient déjà antiques à l’époque de Cléopâtre.$q$, $q$Cléopâtre VII, reine d’Égypte au Ier siècle avant J.-C., vit plus de 2 000 ans après la construction des grandes pyramides de Gizeh. Cela montre l’immense durée de la civilisation égyptienne.$q$, $q$On imagine souvent l’Égypte antique comme une seule époque, mais elle couvre des millénaires. Les pyramides de Gizeh sont construites vers 2500 avant J.-C., tandis que Cléopâtre vit au Ier siècle avant notre ère. Pour elle, les pyramides appartenaient déjà à un passé extrêmement ancien. Cette comparaison donne un repère très parlant sur la profondeur de l’histoire égyptienne.$q$, $q$Encyclopaedia Britannica$q$, $q$https://www.britannica.com/biography/Cleopatra-queen-of-Egypt$q$, 25, $q$#8b5cf6$q$, $q$from-[#17132a] via-[#4c1d95] to-[#a78bfa]$q$),
  ($q$grandes-figures$q$, $q$leonard-de-vinci-etait-autant-inventeur-quartiste$q$, $q$Léonard de Vinci était autant inventeur qu’artiste.$q$, $q$De Vinci incarne la curiosité totale de la Renaissance.$q$, $q$Peintre italien de la Renaissance, Léonard de Vinci est célèbre pour La Joconde et La Cène. Ses carnets montrent aussi des machines, des études du corps humain et des idées très en avance pour son époque.$q$, $q$Léonard de Vinci est souvent résumé à La Joconde, mais son importance dépasse largement la peinture. Il observe le corps, l’eau, les machines, les oiseaux et les mécanismes avec une curiosité permanente. Ses carnets mêlent dessins techniques, recherches scientifiques et projets parfois irréalisables. Il incarne l’idéal de la Renaissance : un esprit capable de relier art, science et invention. C’est pour cela que son nom reste associé au génie polyvalent.$q$, $q$Musée du Louvre$q$, $q$https://www.louvre.fr/$q$, 26, $q$#8b5cf6$q$, $q$from-[#17132a] via-[#4c1d95] to-[#a78bfa]$q$),
  ($q$grandes-figures$q$, $q$rosa-parks-na-pas-seulement-refuse-de-ceder-sa-place$q$, $q$Rosa Parks n’a pas seulement refusé de céder sa place.$q$, $q$Un refus dans un bus déclenche un mouvement immense.$q$, $q$En 1955, Rosa Parks refuse de laisser sa place à un passager blanc dans un bus de Montgomery. Son arrestation provoque un boycott massif et devient un moment clé du mouvement des droits civiques.$q$, $q$Rosa Parks était une militante afro-américaine déjà engagée avant son geste devenu célèbre. Dans l’Alabama ségrégationniste, les bus imposaient des règles racistes. Son refus déclenche le boycott des bus de Montgomery, qui dure plus d’un an. Ce mouvement révèle Martin Luther King au niveau national et montre la force de l’action collective non violente. Rosa Parks devient ainsi un symbole de dignité et de résistance.$q$, $q$National Archives$q$, $q$https://www.archives.gov/education/lessons/rosa-parks$q$, 27, $q$#8b5cf6$q$, $q$from-[#17132a] via-[#4c1d95] to-[#a78bfa]$q$),
  ($q$grandes-figures$q$, $q$gandhi-a-utilise-la-non-violence-comme-arme-politique$q$, $q$Gandhi a utilisé la non-violence comme arme politique.$q$, $q$La résistance pacifique devient une force de masse.$q$, $q$Mahatma Gandhi, leader indien du XXe siècle, lutte contre la domination britannique avec la désobéissance civile et la non-violence. Sa stratégie inspire ensuite de nombreux mouvements dans le monde.$q$, $q$Gandhi ne mène pas une lutte militaire classique. Il organise des marches, des boycotts et des actions symboliques pour contester l’autorité britannique en Inde. Sa méthode repose sur l’idée que refuser d’obéir collectivement peut affaiblir un pouvoir injuste. Son image est complexe, mais son influence politique est immense. La non-violence de Gandhi inspirera notamment Martin Luther King et d’autres combats civiques.$q$, $q$Encyclopaedia Britannica$q$, $q$https://www.britannica.com/biography/Mahatma-Gandhi$q$, 28, $q$#8b5cf6$q$, $q$from-[#17132a] via-[#4c1d95] to-[#a78bfa]$q$),
  ($q$grandes-figures$q$, $q$nelson-mandela-a-passe-27-ans-en-prison$q$, $q$Nelson Mandela a passé 27 ans en prison.$q$, $q$Mandela passe de prisonnier politique à symbole mondial.$q$, $q$Militant contre l’apartheid, Nelson Mandela est emprisonné pendant 27 ans avant de devenir président de l’Afrique du Sud en 1994. Son parcours devient un symbole de résistance et de réconciliation.$q$, $q$Nelson Mandela lutte contre l’apartheid, un système de ségrégation raciale institutionnalisée en Afrique du Sud. Son emprisonnement en fait une figure internationale du combat pour la liberté. À sa libération, il choisit de participer à une transition politique plutôt que d’alimenter une guerre civile. En 1994, il devient le premier président noir du pays. Son histoire est l’un des grands repères politiques du XXe siècle.$q$, $q$Nelson Mandela Foundation$q$, $q$https://www.nelsonmandela.org/content/page/biography$q$, 29, $q$#8b5cf6$q$, $q$from-[#17132a] via-[#4c1d95] to-[#a78bfa]$q$),
  ($q$arts-litterature$q$, $q$van-gogh-na-connu-la-celebrite-quapres-sa-mort$q$, $q$Van Gogh n’a connu la célébrité qu’après sa mort.$q$, $q$Un artiste ignoré devient une icône mondiale.$q$, $q$Vincent van Gogh, peintre néerlandais du XIXe siècle, est aujourd’hui célèbre pour La Nuit étoilée ou ses Tournesols. De son vivant, il vend très peu et vit dans une grande précarité.$q$, $q$Van Gogh est devenu l’image même de l’artiste incompris. Son style, avec ses couleurs intenses et ses coups de pinceau visibles, n’a pas rencontré le succès de son vivant. Après sa mort, son œuvre est progressivement redécouverte et admirée. Ses tableaux comptent aujourd’hui parmi les plus connus au monde. Son destin touche autant parce qu’il mêle talent, fragilité personnelle et reconnaissance tardive.$q$, $q$Van Gogh Museum$q$, $q$https://www.vangoghmuseum.nl/en/art-and-stories/vincent-van-gogh-faq$q$, 30, $q$#06b6d4$q$, $q$from-[#071a20] via-[#164e63] to-[#67e8f9]$q$),
  ($q$arts-litterature$q$, $q$picasso-savait-dessiner-de-maniere-tres-realiste$q$, $q$Picasso savait dessiner de manière très réaliste.$q$, $q$Picasso savait dessiner classique avant de casser les formes.$q$, $q$Pablo Picasso, peintre espagnol du XXe siècle, maîtrise très tôt le dessin académique. Ses œuvres cubistes ne viennent donc pas d’une incapacité à dessiner, mais d’un choix artistique radical.$q$, $q$Picasso est souvent associé à des visages déformés et à des formes géométriques. Pourtant, dans sa jeunesse, il sait parfaitement dessiner de manière réaliste. Le cubisme, qu’il développe avec Georges Braque, cherche à montrer plusieurs points de vue en même temps. Cela explique pourquoi ses œuvres peuvent sembler étranges au premier regard. Elles ne sont pas maladroites : elles essaient de représenter autrement la réalité.$q$, $q$Musée Picasso$q$, $q$https://www.museepicassoparis.fr/$q$, 31, $q$#06b6d4$q$, $q$from-[#071a20] via-[#164e63] to-[#67e8f9]$q$),
  ($q$arts-litterature$q$, $q$la-joconde-est-celebre-aussi-parce-quelle-a-ete-volee$q$, $q$La Joconde est célèbre aussi parce qu’elle a été volée.$q$, $q$Un cambriolage transforme un tableau en phénomène mondial.$q$, $q$En 1911, La Joconde disparaît du Louvre pendant plus de deux ans. L’affaire fait la une des journaux et contribue fortement à transformer le tableau de Léonard de Vinci en icône mondiale.$q$, $q$Avant son vol, La Joconde est déjà une œuvre reconnue, mais elle n’a pas encore son statut actuel d’image planétaire. Sa disparition crée un choc médiatique. Des visiteurs viennent même voir l’emplacement vide au musée. Quand le tableau est retrouvé, sa notoriété a explosé. Ce fait montre comment un événement extérieur à une œuvre peut renforcer sa place dans la culture populaire.$q$, $q$Musée du Louvre$q$, $q$https://www.louvre.fr/decouvrir/le-palais/le-vol-de-la-joconde$q$, 32, $q$#06b6d4$q$, $q$from-[#071a20] via-[#164e63] to-[#67e8f9]$q$),
  ($q$arts-litterature$q$, $q$le-petit-prince-est-lun-des-livres-les-plus-traduits-au-monde$q$, $q$Le Petit Prince est l’un des livres les plus traduits au monde.$q$, $q$Un conte simple cache une réflexion très adulte.$q$, $q$Écrit par Antoine de Saint-Exupéry, Le Petit Prince ressemble à un conte pour enfants. Il parle pourtant de solitude, d’amitié, d’amour et du regard que les adultes portent sur le monde.$q$, $q$Le Petit Prince est publié en 1943. Son style simple le rend accessible, mais ses thèmes parlent aussi aux adultes. Le livre fonctionne sur une double lecture : une aventure poétique pour les enfants, une méditation sur les relations humaines pour les plus grands. Des phrases comme “on ne voit bien qu’avec le cœur” sont devenues célèbres. C’est cette simplicité profonde qui explique son immense diffusion mondiale.$q$, $q$Fondation Antoine de Saint-Exupéry$q$, $q$https://www.fondation-antoine-de-saint-exupery.org/oeuvres/le-petit-prince/$q$, 33, $q$#06b6d4$q$, $q$from-[#071a20] via-[#164e63] to-[#67e8f9]$q$),
  ($q$arts-litterature$q$, $q$frankenstein-a-ete-ecrit-par-mary-shelley-a-seulement-18-ans$q$, $q$Frankenstein a été écrit par Mary Shelley à seulement 18 ans.$q$, $q$Un roman du XIXe siècle pose déjà une question très moderne.$q$, $q$Mary Shelley écrit Frankenstein alors qu’elle est encore très jeune. Le roman raconte une créature fabriquée par un scientifique, mais interroge surtout la responsabilité de l’humain face à ce qu’il crée.$q$, $q$Frankenstein paraît en 1818 et devient l’un des grands textes de la littérature gothique. Beaucoup de gens connaissent le monstre, mais moins le vrai sujet du roman. Mary Shelley ne raconte pas seulement une histoire d’horreur : elle pose une question toujours actuelle, celle des limites de la science et de la responsabilité du créateur. C’est pourquoi Frankenstein reste souvent cité quand on parle de progrès, d’intelligence artificielle ou d’inventions incontrôlées.$q$, $q$British Library$q$, $q$https://www.bl.uk/romantics-and-victorians/articles/frankenstein-the-creation-of-a-monster$q$, 34, $q$#06b6d4$q$, $q$from-[#071a20] via-[#164e63] to-[#67e8f9]$q$),
  ($q$arts-litterature$q$, $q$les-grottes-de-lascaux-ont-ete-decouvertes-par-hasard$q$, $q$Les grottes de Lascaux ont été découvertes par hasard.$q$, $q$Une découverte d’adolescents révèle l’art préhistorique.$q$, $q$En 1940, des adolescents tombent sur des peintures préhistoriques en Dordogne. Ces images montrent que les humains représentaient déjà le monde il y a des milliers d’années.$q$, $q$Les grottes de Lascaux sont découvertes près de Montignac pendant la Seconde Guerre mondiale. Les peintures représentent notamment des chevaux, des taureaux et des cerfs. Elles impressionnent par leur qualité et leur ancienneté. Lascaux rappelle que l’art n’est pas une invention récente : les humains préhistoriques cherchaient déjà à représenter, raconter et peut-être transmettre quelque chose. Le site original est aujourd’hui protégé pour éviter sa dégradation.$q$, $q$Ministère de la Culture$q$, $q$https://archeologie.culture.gouv.fr/lascaux/fr$q$, 35, $q$#06b6d4$q$, $q$from-[#071a20] via-[#164e63] to-[#67e8f9]$q$),
  ($q$science-cerveau$q$, $q$ton-cerveau-reecrit-legerement-tes-souvenirs$q$, $q$Ton cerveau réécrit légèrement tes souvenirs.$q$, $q$Se souvenir, c’est aussi reconstruire.$q$, $q$Quand tu te rappelles quelque chose, ton cerveau ne relit pas un fichier intact. Il reconstruit le souvenir avec des fragments, ce qui explique pourquoi certains souvenirs changent avec le temps.$q$, $q$La mémoire humaine n’est pas une caméra parfaite. À chaque rappel, un souvenir peut être influencé par l’émotion, le contexte ou ce qu’on a appris depuis. Le cerveau reconstruit une version cohérente plutôt qu’un enregistrement exact. Cela explique pourquoi deux personnes peuvent se souvenir différemment d’un même événement. C’est aussi pour cela que les témoignages humains peuvent être sincères, mais imparfaits.$q$, $q$American Psychological Association$q$, $q$https://www.apa.org/topics/memory$q$, 36, $q$#22c55e$q$, $q$from-[#061a12] via-[#14532d] to-[#86efac]$q$),
  ($q$science-cerveau$q$, $q$ton-cerveau-ignore-des-details-pour-eviter-la-surcharge$q$, $q$Ton cerveau ignore des détails pour éviter la surcharge.$q$, $q$Voir ne signifie pas forcément remarquer.$q$, $q$Le cerveau trie en permanence ce que les yeux lui envoient. Ce filtrage est utile, mais il explique aussi pourquoi un détail pourtant visible peut passer totalement inaperçu.$q$, $q$Nos yeux captent énormément d’informations à chaque seconde. Pour ne pas être submergé, le cerveau sélectionne ce qui semble important selon l’attention, le contexte ou les habitudes. Ce mécanisme permet de se concentrer, mais il a un prix : on peut manquer quelque chose d’évident. Les illusions et les expériences d’inattention visuelle montrent que notre perception du monde est une construction active.$q$, $q$American Psychological Association$q$, $q$https://www.apa.org/topics/sensation-perception$q$, 37, $q$#22c55e$q$, $q$from-[#061a12] via-[#14532d] to-[#86efac]$q$),
  ($q$science-cerveau$q$, $q$le-miel-peut-rester-consommable-pendant-des-milliers-dannees$q$, $q$Le miel peut rester consommable pendant des milliers d’années.$q$, $q$Le miel se conserve parce qu’il bloque les bactéries.$q$, $q$Le miel contient très peu d’eau et crée un environnement difficile pour la plupart des bactéries. C’est pour cela qu’on a retrouvé du miel très ancien encore remarquablement bien conservé.$q$, $q$Le miel est l’un des aliments les plus étonnants pour la conservation. Sa faible quantité d’eau empêche beaucoup de micro-organismes de se développer. Son acidité et certaines substances naturelles renforcent aussi cette protection. Bien conservé, il peut cristalliser ou changer d’aspect, mais rester consommable. Ce fait est facile à retenir parce qu’il transforme un aliment très familier en objet presque archéologique.$q$, $q$Smithsonian Magazine$q$, $q$https://www.smithsonianmag.com/smart-news/what-is-the-shelf-life-of-honey-121676707/$q$, 38, $q$#22c55e$q$, $q$from-[#061a12] via-[#14532d] to-[#86efac]$q$),
  ($q$science-cerveau$q$, $q$les-bananes-sont-legerement-radioactives$q$, $q$Les bananes sont légèrement radioactives.$q$, $q$Un fruit banal contient une radioactivité naturelle inoffensive.$q$, $q$Les bananes contiennent naturellement du potassium, dont une petite partie émet de faibles radiations. La quantité est totalement inoffensive, mais l’idée surprend parce qu’il s’agit d’un fruit très courant.$q$, $q$La radioactivité n’est pas toujours liée aux centrales nucléaires ou aux accidents. Elle existe aussi naturellement autour de nous, à des niveaux très faibles. Les bananes en sont un exemple connu à cause du potassium qu’elles contiennent. Cela ne les rend pas dangereuses : il faudrait des quantités absurdes pour poser problème. Le fait est surtout intéressant parce qu’il rend concret un phénomène souvent perçu comme lointain ou inquiétant.$q$, $q$United States Environmental Protection Agency$q$, $q$https://www.epa.gov/radiation/radiation-sources-and-doses$q$, 39, $q$#22c55e$q$, $q$from-[#061a12] via-[#14532d] to-[#86efac]$q$),
  ($q$science-cerveau$q$, $q$les-pieuvres-ont-trois-coeurs$q$, $q$Les pieuvres ont trois cœurs.$q$, $q$Deux cœurs servent aux branchies, un autre au reste du corps.$q$, $q$Chez la pieuvre, deux cœurs envoient le sang vers les branchies, tandis qu’un troisième l’envoie vers les organes. C’est l’un des détails qui rendent ces animaux si différents de nous.$q$, $q$Les pieuvres sont des animaux très particuliers, bien loin de notre anatomie de mammifères. Leur sang, leur système nerveux et leur manière de se déplacer diffèrent fortement des nôtres. Leurs trois cœurs ont chacun un rôle dans la circulation du sang. Ce fait marque facilement les esprits car il donne une image simple : un animal connu, mais construit selon une logique presque étrangère à la nôtre.$q$, $q$Smithsonian Ocean$q$, $q$https://ocean.si.edu/ocean-life/invertebrates/octopus$q$, 40, $q$#22c55e$q$, $q$from-[#061a12] via-[#14532d] to-[#86efac]$q$),
  ($q$science-cerveau$q$, $q$une-journee-sur-venus-dure-plus-longtemps-quune-annee-sur-venus$q$, $q$Une journée sur Vénus dure plus longtemps qu’une année sur Vénus.$q$, $q$Sur Vénus, la rotation est plus lente que l’orbite.$q$, $q$Vénus tourne extrêmement lentement sur elle-même. Elle met plus de temps à faire un tour complet sur son axe qu’à faire le tour du Soleil.$q$, $q$Une journée correspond au temps qu’une planète met à tourner sur elle-même. Une année correspond au temps qu’elle met à faire le tour du Soleil. Sur Terre, la différence est évidente. Sur Vénus, tout semble inversé : sa rotation est si lente qu’elle dépasse la durée de son année. Ce fait est utile parce qu’il montre que des mots familiers comme “jour” ou “année” dépendent en réalité du mouvement des planètes.$q$, $q$NASA$q$, $q$https://solarsystem.nasa.gov/planets/venus/in-depth/$q$, 41, $q$#22c55e$q$, $q$from-[#061a12] via-[#14532d] to-[#86efac]$q$),
  ($q$science-cerveau$q$, $q$le-sommeil-aide-ton-cerveau-a-trier-la-journee$q$, $q$Le sommeil aide ton cerveau à trier la journée.$q$, $q$Dormir aide aussi à ranger les souvenirs.$q$, $q$Pendant le sommeil, le cerveau consolide certains souvenirs et en laisse d’autres de côté. Dormir ne sert donc pas seulement à récupérer physiquement.$q$, $q$Le sommeil joue un rôle important dans la mémoire et l’apprentissage. Pendant certaines phases de la nuit, le cerveau réactive des informations récentes et renforce celles qui semblent utiles. C’est l’une des raisons pour lesquelles une bonne nuit peut aider après une journée d’apprentissage. Le cerveau ne se met pas simplement en pause : il continue à organiser ce que nous avons vécu.$q$, $q$NIH News in Health$q$, $q$https://newsinhealth.nih.gov/2013/04/benefits-slumber$q$, 42, $q$#22c55e$q$, $q$from-[#061a12] via-[#14532d] to-[#86efac]$q$),
  ($q$inventions-technologie$q$, $q$le-premier-iphone-ne-permettait-pas-de-copier-coller$q$, $q$Le premier iPhone ne permettait pas de copier-coller.$q$, $q$Même révolutionnaire, le premier iPhone était incomplet.$q$, $q$Présenté en 2007 par Steve Jobs, le premier iPhone impressionne par son écran tactile et sa simplicité. Pourtant, il ne propose pas encore certaines fonctions aujourd’hui basiques, comme le copier-coller.$q$, $q$Avant l’iPhone, beaucoup de téléphones reposent sur des claviers physiques et des menus peu fluides. Apple propose un appareil presque entièrement contrôlé au doigt, ce qui donne une impression de simplicité nouvelle. Mais le produit est loin d’être complet : pas de copier-coller au lancement, pas d’App Store au début, et des limites techniques importantes. Son succès montre qu’une innovation peut changer les usages même en commençant imparfaite.$q$, $q$Apple$q$, $q$https://www.apple.com/newsroom/2007/01/09Apple-Reinvents-the-Phone-with-iPhone/$q$, 43, $q$#3b82f6$q$, $q$from-[#071426] via-[#1d4ed8] to-[#93c5fd]$q$),
  ($q$inventions-technologie$q$, $q$internet-vient-dun-projet-militaire-et-universitaire$q$, $q$Internet vient d’un projet militaire et universitaire.$q$, $q$Internet commence comme un réseau d’institutions.$q$, $q$Avant de devenir un outil du quotidien, Internet sert à connecter des ordinateurs entre centres de recherche et institutions. Ce réseau expérimental finira par transformer presque toute la vie moderne.$q$, $q$Internet ne naît pas d’un seul inventeur ni d’une idée commerciale simple. Ses racines se trouvent dans ARPANET, un réseau développé aux États-Unis pour relier des ordinateurs de recherche. L’objectif est d’échanger des informations entre machines éloignées. Avec le temps, les protocoles se standardisent et le réseau s’ouvre. Ce qui était un outil spécialisé devient l’infrastructure de nos messages, recherches, vidéos, achats et relations sociales.$q$, $q$Internet Society$q$, $q$https://www.internetsociety.org/internet/history-internet/brief-history-internet/$q$, 44, $q$#3b82f6$q$, $q$from-[#071426] via-[#1d4ed8] to-[#93c5fd]$q$),
  ($q$inventions-technologie$q$, $q$le-premier-email-a-ete-envoye-dans-les-annees-1970$q$, $q$Le premier email a été envoyé dans les années 1970.$q$, $q$Le symbole @ devient central grâce à l’email.$q$, $q$Le premier email moderne est envoyé au début des années 1970. Le symbole @ sert à séparer le nom de l’utilisateur et celui de la machine, une convention devenue mondiale.$q$, $q$L’email apparaît avant l’Internet grand public. À l’époque, il sert surtout à envoyer des messages entre utilisateurs d’ordinateurs connectés à des réseaux de recherche. Ray Tomlinson popularise l’usage du symbole @ pour indiquer qu’un utilisateur se trouve “chez” une machine. Ce petit signe typographique devient ensuite l’un des symboles les plus reconnaissables de l’ère numérique.$q$, $q$Computer History Museum$q$, $q$https://www.computerhistory.org/internethistory/1970s/$q$, 45, $q$#3b82f6$q$, $q$from-[#071426] via-[#1d4ed8] to-[#93c5fd]$q$),
  ($q$inventions-technologie$q$, $q$le-gps-depend-dhorloges-extremement-precises$q$, $q$Le GPS dépend d’horloges extrêmement précises.$q$, $q$Le GPS repose surtout sur une mesure du temps.$q$, $q$Ton téléphone calcule sa position en comparant des signaux envoyés par plusieurs satellites. Si le temps mesuré est imprécis, la localisation devient vite fausse.$q$, $q$Le GPS ne fonctionne pas simplement parce que des satellites “voient” ton téléphone. Chaque satellite envoie un signal contenant l’heure exacte de son émission. Le téléphone compare le temps mis par plusieurs signaux pour arriver jusqu’à lui. De minuscules erreurs de temps peuvent devenir de grandes erreurs de distance. C’est pourquoi les satellites GPS utilisent des horloges extrêmement précises. Ce système montre à quel point la localisation moderne dépend d’une maîtrise fine du temps.$q$, $q$NASA$q$, $q$https://www.nasa.gov/directorates/somd/space-communications-navigation-program/gps/$q$, 46, $q$#3b82f6$q$, $q$from-[#071426] via-[#1d4ed8] to-[#93c5fd]$q$),
  ($q$inventions-technologie$q$, $q$le-qr-code-a-ete-invente-pour-suivre-des-pieces-automobiles$q$, $q$Le QR code a été inventé pour suivre des pièces automobiles.$q$, $q$Un outil d’usine est devenu un geste du quotidien.$q$, $q$Créé au Japon dans les années 1990, le QR code sert d’abord à identifier rapidement des pièces automobiles. Il est ensuite devenu courant pour les menus, billets, paiements et connexions.$q$, $q$Le QR code est inventé par Denso Wave pour répondre à un besoin industriel : stocker plus d’informations qu’un code-barres classique et les lire rapidement. Sa forme en petits carrés permet une lecture efficace, même si le code est partiellement abîmé. Pendant longtemps, il reste surtout technique. Avec les smartphones et la pandémie, il devient un geste quotidien. Scanner un QR code est aujourd’hui devenu presque aussi banal que cliquer sur un lien.$q$, $q$DENSO Wave$q$, $q$https://www.qrcode.com/en/history/$q$, 47, $q$#3b82f6$q$, $q$from-[#071426] via-[#1d4ed8] to-[#93c5fd]$q$),
  ($q$inventions-technologie$q$, $q$bluetooth-porte-le-nom-dun-roi-viking$q$, $q$Bluetooth porte le nom d’un roi viking.$q$, $q$Une technologie sans fil cache une référence médiévale.$q$, $q$Le nom Bluetooth vient de Harald “Bluetooth”, un roi viking associé à l’unification de territoires. Les créateurs de la technologie voulaient, eux aussi, relier différents appareils entre eux.$q$, $q$Bluetooth est une technologie moderne, mais son nom vient du Moyen Âge scandinave. Harald Bluetooth est connu pour avoir uni des groupes autour du Danemark. Les ingénieurs ont trouvé l’image pertinente : leur technologie devait permettre à des appareils différents de communiquer. Même le logo Bluetooth combine des runes liées aux initiales du roi. C’est un bon exemple de référence historique cachée dans un objet numérique du quotidien.$q$, $q$Bluetooth SIG$q$, $q$https://www.bluetooth.com/about-us/bluetooth-origin/$q$, 48, $q$#3b82f6$q$, $q$from-[#071426] via-[#1d4ed8] to-[#93c5fd]$q$),
  ($q$quotidien-societe$q$, $q$le-week-end-de-deux-jours-sest-generalise-au-xxe-siecle$q$, $q$Le week-end de deux jours s’est surtout généralisé au XXe siècle.$q$, $q$Avoir deux jours de repos est une conquête récente.$q$, $q$Pendant longtemps, beaucoup de travailleurs n’avaient qu’un seul jour de repos, souvent le dimanche. Le samedi libre se développe progressivement avec les luttes sociales, la réduction du temps de travail et l’industrialisation.$q$, $q$Le week-end n’est pas une évidence naturelle : c’est une construction sociale. Au XIXe siècle, beaucoup d’ouvriers travaillent six jours par semaine, parfois davantage. Les revendications pour limiter le temps de travail deviennent plus fortes avec les syndicats et les mouvements sociaux. Dans plusieurs pays industrialisés, le samedi après-midi puis le samedi entier deviennent progressivement du temps libre au XXe siècle. Après la Seconde Guerre mondiale, le week-end de deux jours devient beaucoup plus courant.$q$, $q$Encyclopaedia Britannica$q$, $q$https://www.britannica.com/topic/week$q$, 49, $q$#f59e0b$q$, $q$from-[#1c1608] via-[#92400e] to-[#fbbf24]$q$),
  ($q$quotidien-societe$q$, $q$les-soldes-servent-aussi-a-vider-les-stocks$q$, $q$Les soldes servent aussi à vider les stocks.$q$, $q$Une réduction est souvent un outil de gestion.$q$, $q$Pour les magasins, baisser les prix permet d’écouler les produits avant une nouvelle saison. Les soldes ne sont donc pas seulement un cadeau au client, mais aussi une stratégie commerciale.$q$, $q$Les soldes répondent à une logique économique simple : un produit invendu coûte de la place, immobilise de l’argent et peut perdre de la valeur. Les commerçants préfèrent parfois réduire leur marge pour libérer les stocks. En France, les soldes sont encadrés par des périodes officielles. Ce fait aide à comprendre que le prix n’est pas seulement lié à la valeur d’un objet, mais aussi au moment, au stock et à la stratégie du vendeur.$q$, $q$Service public$q$, $q$https://www.service-public.fr/particuliers/vosdroits/F1015$q$, 50, $q$#f59e0b$q$, $q$from-[#1c1608] via-[#92400e] to-[#fbbf24]$q$),
  ($q$quotidien-societe$q$, $q$les-files-dattente-ont-leurs-propres-regles-sociales$q$, $q$Les files d’attente ont leurs propres règles sociales.$q$, $q$Attendre paraît simple, mais c’est très codifié.$q$, $q$Respecter l’ordre, garder une distance ou s’agacer contre ceux qui doublent montre que la file repose sur une idée partagée de justice. Un geste banal révèle une règle sociale forte.$q$, $q$Une file d’attente semble naturelle, mais elle repose sur un contrat implicite : premier arrivé, premier servi. Quand quelqu’un double, la réaction est souvent forte parce que la règle paraît injustement brisée. Les files varient selon les cultures, les lieux et les contextes, mais elles montrent toutes comment les humains organisent l’attente. C’est un exemple simple de norme sociale invisible : tout le monde la connaît sans qu’elle soit toujours écrite.$q$, $q$BBC$q$, $q$https://www.bbc.com/future/article/20150512-why-queues-are-fair$q$, 51, $q$#f59e0b$q$, $q$from-[#1c1608] via-[#92400e] to-[#fbbf24]$q$),
  ($q$quotidien-societe$q$, $q$les-jeans-etaient-dabord-des-vetements-de-travail$q$, $q$Les jeans étaient d’abord des vêtements de travail.$q$, $q$Le jean passe de l’atelier au vêtement universel.$q$, $q$Leur tissu solide convenait aux ouvriers, mineurs et chercheurs d’or. Avec le temps, le jean quitte le monde du travail pour devenir l’un des vêtements les plus portés au monde.$q$, $q$Le jean est associé aujourd’hui à la mode, à la jeunesse ou à la décontraction. À l’origine, il répond surtout à un besoin pratique : résister à un travail physique difficile. Levi Strauss et Jacob Davis popularisent des pantalons renforcés adaptés aux travailleurs. Au XXe siècle, le jean devient un symbole culturel, porté par des acteurs, des musiciens et des mouvements de jeunesse. Son histoire montre comment un objet utilitaire peut devenir un code social mondial.$q$, $q$Levi Strauss & Co.$q$, $q$https://www.levistrauss.com/2014/06/27/the-origin-of-blue-jeans/$q$, 52, $q$#f59e0b$q$, $q$from-[#1c1608] via-[#92400e] to-[#fbbf24]$q$),
  ($q$quotidien-societe$q$, $q$les-talons-hauts-etaient-dabord-portes-par-des-hommes$q$, $q$Les talons hauts étaient d’abord portés par des hommes.$q$, $q$Les talons étaient liés aux cavaliers avant la mode féminine.$q$, $q$Avant de devenir un symbole souvent associé aux femmes, les talons servent notamment à certains cavaliers pour mieux tenir les étriers. Leur sens social change ensuite au fil des siècles.$q$, $q$Les talons hauts ont une histoire plus complexe que l’image moderne qu’on en a. Dans certaines cultures, ils sont liés à la pratique équestre et au statut social masculin. À la cour, ils deviennent aussi un signe de distinction. Plus tard, la mode évolue et les talons se féminisent progressivement en Europe. Ce fait est intéressant parce qu’il montre que les codes vestimentaires que l’on croit évidents sont souvent des constructions historiques changeantes.$q$, $q$Victoria and Albert Museum$q$, $q$https://www.vam.ac.uk/articles/a-history-of-shoes$q$, 53, $q$#f59e0b$q$, $q$from-[#1c1608] via-[#92400e] to-[#fbbf24]$q$),
  ($q$quotidien-societe$q$, $q$les-supermarches-sont-penses-pour-guider-tes-choix$q$, $q$Les supermarchés sont pensés pour guider tes choix.$q$, $q$Les rayons orientent tes achats sans en avoir l’air.$q$, $q$L’emplacement des produits, les promotions, les parcours et les têtes de gondole ne sont pas laissés au hasard. Tout est conçu pour rendre certains achats plus visibles ou plus tentants.$q$, $q$Un supermarché n’est pas seulement un lieu où les produits sont rangés. Les marques et les distributeurs réfléchissent à la visibilité, au passage et aux habitudes des clients. Les produits essentiels peuvent être éloignés pour faire traverser plusieurs rayons. Les promotions sont placées dans des zones très visibles. Même la hauteur des étagères compte. Comprendre cela aide à voir que beaucoup de décisions d’achat sont influencées par l’environnement.$q$, $q$NielsenIQ$q$, $q$https://nielseniq.com/global/en/insights/$q$, 54, $q$#f59e0b$q$, $q$from-[#1c1608] via-[#92400e] to-[#fbbf24]$q$),
  ($q$mots-origines$q$, $q$le-mot-robot-vient-dun-mot-lie-au-travail-force$q$, $q$Le mot robot vient d’un mot lié au travail forcé.$q$, $q$À l’origine, le robot est imaginé comme un travailleur artificiel.$q$, $q$Le mot apparaît dans une pièce tchèque des années 1920. Il vient d’une racine liée au travail pénible ou forcé, ce qui explique pourquoi les premiers robots de fiction sont pensés comme des serviteurs humains.$q$, $q$Le mot “robot” est popularisé par la pièce R.U.R. de Karel Čapek, publiée en 1920. Dans cette œuvre, les robots ne sont pas d’abord des machines métalliques comme dans la science-fiction moderne : ce sont des êtres artificiels conçus pour travailler à la place des humains. Le mot garde donc une inquiétude sociale dès son origine. Il pose déjà une question actuelle : que devient l’humain quand il crée des travailleurs artificiels ?$q$, $q$Science Museum$q$, $q$https://www.sciencemuseum.org.uk/objects-and-stories/robots$q$, 55, $q$#14b8a6$q$, $q$from-[#06221f] via-[#0f766e] to-[#5eead4]$q$),
  ($q$mots-origines$q$, $q$le-mot-salaire-est-lie-au-sel$q$, $q$Le mot salaire est lié au sel.$q$, $q$Le salaire garde la trace d’une valeur ancienne : le sel.$q$, $q$Le mot vient du latin salarium, lié au sel, une ressource précieuse dans l’Antiquité romaine. Cela rappelle qu’un aliment banal aujourd’hui pouvait autrefois avoir une grande valeur économique.$q$, $q$Dans l’Antiquité, le sel sert à conserver les aliments et joue un rôle important dans la vie quotidienne. Son importance économique explique son lien avec certains paiements ou allocations dans le monde romain. Le mot latin salarium a ensuite donné “salaire”. Même si les détails historiques sont parfois simplifiés, l’origine du mot reste une bonne manière de voir comment les besoins matériels laissent des traces dans la langue.$q$, $q$Dictionnaire de l’Académie française$q$, $q$https://www.dictionnaire-academie.fr/article/A9S0175$q$, 56, $q$#14b8a6$q$, $q$from-[#06221f] via-[#0f766e] to-[#5eead4]$q$),
  ($q$mots-origines$q$, $q$le-mot-deadline-avait-autrefois-un-sens-beaucoup-plus-sombre$q$, $q$Le mot deadline avait autrefois un sens beaucoup plus sombre.$q$, $q$Deadline désignait d’abord une limite bien plus dangereuse.$q$, $q$Pendant la guerre de Sécession, le mot désigne une ligne à ne pas franchir dans certains camps de prisonniers. Il évolue ensuite pour désigner une limite de temps.$q$, $q$Aujourd’hui, une deadline est simplement une échéance. Son origine est beaucoup plus brutale. Dans certains camps de prisonniers américains au XIXe siècle, la “dead line” est une ligne physique que les détenus ne doivent pas franchir sous peine d’être abattus. Le mot perd ensuite son sens littéral et devient une métaphore : une limite qu’il ne faut pas dépasser. C’est un exemple frappant d’un mot courant au passé oublié.$q$, $q$Merriam-Webster$q$, $q$https://www.merriam-webster.com/wordplay/your-deadline-wont-kill-you$q$, 57, $q$#14b8a6$q$, $q$from-[#06221f] via-[#0f766e] to-[#5eead4]$q$),
  ($q$mots-origines$q$, $q$le-mot-boycott-vient-du-nom-dun-homme$q$, $q$Le mot boycott vient du nom d’un homme.$q$, $q$Un nom propre devient un mot politique mondial.$q$, $q$Charles Boycott était un agent foncier en Irlande au XIXe siècle. Des habitants refusent de travailler avec lui ou de lui vendre des services, et son nom finit par désigner ce type de refus collectif.$q$, $q$Le boycott est aujourd’hui une action politique ou économique très connue : refuser d’acheter, de participer ou de coopérer. Le mot vient d’un épisode précis en Irlande, où Charles Boycott est isolé socialement et économiquement par des habitants. L’affaire est relayée dans la presse et son nom devient un verbe, puis un nom commun. C’est un exemple parfait d’événement local devenu mot universel.$q$, $q$Encyclopaedia Britannica$q$, $q$https://www.britannica.com/topic/boycott$q$, 58, $q$#14b8a6$q$, $q$from-[#06221f] via-[#0f766e] to-[#5eead4]$q$),
  ($q$mots-origines$q$, $q$le-mot-sandwich-vient-dun-comte-anglais$q$, $q$Le mot sandwich vient d’un comte anglais.$q$, $q$Un nom de noble devient celui d’un repas mondial.$q$, $q$Le terme viendrait du comte de Sandwich, aristocrate britannique du XVIIIe siècle. Il aurait popularisé l’idée de manger de la viande entre deux tranches de pain sans interrompre ses activités.$q$, $q$L’histoire du sandwich est souvent racontée avec une part de légende, mais le lien avec John Montagu, comte de Sandwich, est resté célèbre. L’idée d’un repas pratique, qu’on peut manger sans couverts, existait sûrement déjà sous d’autres formes. Ce qui est marquant, c’est qu’un titre de noblesse devienne le nom d’un aliment quotidien mondial. Le mot rappelle comment l’usage social peut fixer une expression dans la langue.$q$, $q$Oxford English Dictionary$q$, $q$https://www.oed.com/$q$, 59, $q$#14b8a6$q$, $q$from-[#06221f] via-[#0f766e] to-[#5eead4]$q$),
  ($q$geographie-monde$q$, $q$les-cartes-du-monde-deforment-la-taille-reelle-des-pays$q$, $q$Les cartes du monde déforment la taille réelle des pays.$q$, $q$Une carte plate ne peut pas respecter toutes les tailles.$q$, $q$Sur certaines cartes, le Groenland paraît presque aussi grand que l’Afrique. En réalité, l’Afrique est environ 14 fois plus vaste, car représenter une planète ronde sur une surface plate crée forcément des déformations.$q$, $q$Une carte est toujours un compromis. Pour représenter une sphère sur une feuille, il faut déformer soit les tailles, soit les formes, soit les distances. La projection de Mercator, très utilisée, agrandit les régions proches des pôles. Cela peut donner une vision faussée de l’importance visuelle des continents. Comprendre ce biais aide à regarder les cartes non comme des copies parfaites du monde, mais comme des outils construits selon un objectif.$q$, $q$National Geographic$q$, $q$https://education.nationalgeographic.org/resource/map-projections/$q$, 60, $q$#84cc16$q$, $q$from-[#101a08] via-[#3f6212] to-[#bef264]$q$),
  ($q$geographie-monde$q$, $q$istanbul-est-a-cheval-sur-deux-continents$q$, $q$Istanbul est à cheval sur deux continents.$q$, $q$Une partie de la ville est en Europe, l’autre en Asie.$q$, $q$Le détroit du Bosphore sépare Istanbul en deux rives : l’une européenne, l’autre asiatique. Cette position explique son rôle historique de carrefour entre plusieurs mondes.$q$, $q$Istanbul a porté plusieurs noms et plusieurs identités : Byzance, Constantinople, puis Istanbul. Sa position au bord du Bosphore en fait un passage stratégique entre la Méditerranée, la mer Noire, l’Europe et l’Asie. Pendant des siècles, la ville a été un centre politique, commercial et religieux majeur. Comprendre sa géographie aide à comprendre pourquoi elle a tant compté dans l’histoire byzantine, ottomane et moderne.$q$, $q$Encyclopaedia Britannica$q$, $q$https://www.britannica.com/place/Istanbul$q$, 61, $q$#84cc16$q$, $q$from-[#101a08] via-[#3f6212] to-[#bef264]$q$),
  ($q$geographie-monde$q$, $q$lantarctique-est-un-desert$q$, $q$L’Antarctique est un désert.$q$, $q$Un désert se définit surtout par le manque de précipitations.$q$, $q$Même couvert de glace, l’Antarctique reçoit très peu de pluie ou de neige. Un désert n’est donc pas forcément chaud : c’est d’abord un endroit où il tombe très peu d’eau.$q$, $q$On associe souvent les déserts au sable et à la chaleur. L’Antarctique montre que cette image est incomplète. Le continent est extrêmement froid, mais aussi très sec. Une grande partie de l’eau y est piégée sous forme de glace, et les précipitations sont faibles. Ce fait est utile car il corrige une définition courante : le désert est d’abord une question d’aridité, pas de température.$q$, $q$National Geographic$q$, $q$https://education.nationalgeographic.org/resource/desert/$q$, 62, $q$#84cc16$q$, $q$from-[#101a08] via-[#3f6212] to-[#bef264]$q$),
  ($q$geographie-monde$q$, $q$venise-est-construite-sur-une-lagune$q$, $q$Venise est construite sur une lagune.$q$, $q$Venise est belle parce qu’elle est aussi fragile.$q$, $q$La ville repose sur des îlots et des structures en bois enfoncées dans un sol humide. Cette relation permanente avec l’eau rend son architecture fascinante, mais aussi vulnérable.$q$, $q$Venise ne se comprend pas comme une ville classique posée sur la terre ferme. Elle s’est développée dans une lagune, sur un ensemble d’îlots reliés par des ponts et des canaux. Les fondations utilisent notamment des pieux en bois, conservés par le manque d’oxygène sous l’eau. Cette adaptation remarquable a créé une ville unique, mais exposée aux inondations, à l’érosion et au tourisme de masse. Sa beauté vient en partie de cette fragilité.$q$, $q$UNESCO$q$, $q$https://whc.unesco.org/en/list/394/$q$, 63, $q$#84cc16$q$, $q$from-[#101a08] via-[#3f6212] to-[#bef264]$q$),
  ($q$geographie-monde$q$, $q$la-mer-morte-est-si-salee-quon-y-flotte-facilement$q$, $q$La mer Morte est si salée qu’on y flotte facilement.$q$, $q$Le sel rend l’eau assez dense pour porter le corps.$q$, $q$La mer Morte contient beaucoup plus de sel que la plupart des mers. Cette forte salinité rend l’eau plus dense, ce qui donne cette sensation étrange de flotter presque sans effort.$q$, $q$La mer Morte est en réalité un lac salé situé entre Israël, la Cisjordanie et la Jordanie. Comme l’eau s’évapore beaucoup et que les sorties naturelles sont limitées, les sels s’accumulent. Cette concentration rend la baignade très particulière : le corps flotte plus facilement qu’ailleurs. Le lieu est aussi célèbre pour son altitude très basse et son importance historique dans la région. C’est un exemple parlant de géographie que l’on ressent physiquement.$q$, $q$Encyclopaedia Britannica$q$, $q$https://www.britannica.com/place/Dead-Sea$q$, 64, $q$#84cc16$q$, $q$from-[#101a08] via-[#3f6212] to-[#bef264]$q$),
  ($q$musique-culture$q$, $q$mozart-composait-deja-enfant$q$, $q$Mozart composait déjà enfant.$q$, $q$Mozart symbolise le génie musical très précoce.$q$, $q$Wolfgang Amadeus Mozart, compositeur autrichien du XVIIIe siècle, joue et compose très jeune. Son nom est devenu l’exemple classique de l’enfant prodige en musique.$q$, $q$Mozart grandit dans une famille de musiciens et se produit très tôt devant les cours européennes. Il compose des œuvres dans de nombreux genres : opéras, symphonies, concertos, musique religieuse. Même ceux qui ne connaissent pas précisément ses morceaux associent son nom à une virtuosité précoce. Des œuvres comme La Flûte enchantée ou Don Giovanni expliquent pourquoi il reste l’une des grandes références de la musique classique.$q$, $q$Encyclopaedia Britannica$q$, $q$https://www.britannica.com/biography/Wolfgang-Amadeus-Mozart$q$, 65, $q$#ef4444$q$, $q$from-[#220b0b] via-[#991b1b] to-[#fca5a5]$q$),
  ($q$musique-culture$q$, $q$beethoven-a-compose-alors-quil-devenait-sourd$q$, $q$Beethoven a composé alors qu’il devenait sourd.$q$, $q$Beethoven crée de la musique malgré une audition qui disparaît.$q$, $q$Ludwig van Beethoven, compositeur allemand du début du XIXe siècle, perd progressivement l’audition. Il continue pourtant à composer certaines de ses œuvres les plus célèbres.$q$, $q$Beethoven est l’une des grandes figures de la musique classique. Sa surdité progressive rend son parcours particulièrement impressionnant, car son art repose précisément sur le son. Il compose en s’appuyant sur sa mémoire musicale, sa maîtrise de la structure et son imagination intérieure. Sa Neuvième Symphonie, avec l’Ode à la joie, reste l’une de ses œuvres les plus connues. Son histoire symbolise la force créative face à une limite personnelle immense.$q$, $q$Beethoven-Haus Bonn$q$, $q$https://www.beethoven.de/en/beethoven$q$, 66, $q$#ef4444$q$, $q$from-[#220b0b] via-[#991b1b] to-[#fca5a5]$q$),
  ($q$musique-culture$q$, $q$les-beatles-ont-transforme-la-musique-populaire$q$, $q$Les Beatles ont transformé la musique populaire.$q$, $q$Les Beatles changent autant l’album que la chanson.$q$, $q$Groupe britannique des années 1960, les Beatles ne se contentent pas d’enchaîner les tubes. Ils changent la manière d’enregistrer, d’écrire des albums et de penser l’image d’un groupe.$q$, $q$Les Beatles commencent comme un groupe pop très populaire, puis deviennent un laboratoire musical. Avec des albums comme Sgt. Pepper’s Lonely Hearts Club Band, ils montrent que l’album peut être plus qu’une simple collection de chansons. Ils expérimentent en studio, travaillent leur image et influencent durablement la culture jeune. Leur impact dépasse largement la musique : mode, médias, célébrité et culture populaire mondiale.$q$, $q$The Beatles$q$, $q$https://www.thebeatles.com/$q$, 67, $q$#ef4444$q$, $q$from-[#220b0b] via-[#991b1b] to-[#fca5a5]$q$),
  ($q$musique-culture$q$, $q$le-hip-hop-est-ne-dans-le-bronx-dans-les-annees-1970$q$, $q$Le hip-hop est né dans le Bronx dans les années 1970.$q$, $q$Une culture de quartier devient un mouvement mondial.$q$, $q$Au départ, le hip-hop rassemble musique, danse, graffiti et art de la parole. Ce qui naît dans des fêtes de quartier new-yorkaises devient l’un des mouvements culturels les plus influents du monde.$q$, $q$Le hip-hop émerge dans le Bronx, à New York, dans un contexte social difficile. Les DJ, les MC, les danseurs et les graffeurs créent une culture complète autour du rythme, de la parole et de l’expression urbaine. Le rap en devient l’une des formes les plus visibles, mais le hip-hop ne se limite pas à la musique. Il porte aussi une histoire de créativité, d’identité et de contestation sociale. Aujourd’hui, son influence est mondiale.$q$, $q$Smithsonian Music$q$, $q$https://music.si.edu/spotlight/hip-hop$q$, 68, $q$#ef4444$q$, $q$from-[#220b0b] via-[#991b1b] to-[#fca5a5]$q$),
  ($q$musique-culture$q$, $q$bob-marley-a-rendu-le-reggae-mondialement-celebre$q$, $q$Bob Marley a rendu le reggae mondialement célèbre.$q$, $q$Bob Marley fait du reggae une langue mondiale.$q$, $q$Chanteur jamaïcain du XXe siècle, Bob Marley porte le reggae bien au-delà de la Jamaïque. Ses chansons restent associées à la paix, à la résistance et à une identité culturelle forte.$q$, $q$Bob Marley n’a pas inventé le reggae, mais il l’a rendu visible à l’échelle mondiale. Sa musique mêle rythmes jamaïcains, spiritualité rastafari et messages politiques. Des titres comme No Woman, No Cry, Redemption Song ou One Love sont devenus des classiques. Il incarne une musique à la fois populaire et engagée. Connaître Bob Marley, c’est comprendre une porte d’entrée essentielle vers la culture jamaïcaine moderne.$q$, $q$Rock & Roll Hall of Fame$q$, $q$https://rockhall.com/inductees/bob-marley/$q$, 69, $q$#ef4444$q$, $q$from-[#220b0b] via-[#991b1b] to-[#fca5a5]$q$),
  ($q$musique-culture$q$, $q$la-marseillaise-etait-dabord-un-chant-de-guerre$q$, $q$La Marseillaise était d’abord un chant de guerre.$q$, $q$L’hymne français garde l’énergie d’un chant révolutionnaire.$q$, $q$Écrite en 1792, La Marseillaise accompagne un contexte révolutionnaire et militaire. Elle devient ensuite l’hymne national français, ce qui explique son ton intense et combatif.$q$, $q$La Marseillaise est composée par Rouget de Lisle pendant la Révolution française, au moment où la France est en guerre contre des monarchies européennes. Le chant appelle à la mobilisation et à la défense de la patrie. Son vocabulaire peut surprendre aujourd’hui, mais il correspond à un contexte de guerre et de révolution. Devenu hymne national, il garde cette charge historique. Le connaître, c’est mieux comprendre pourquoi l’hymne français a une telle intensité.$q$, $q$Élysée$q$, $q$https://www.elysee.fr/la-presidence/la-marseillaise-de-rouget-de-lisle$q$, 70, $q$#ef4444$q$, $q$from-[#220b0b] via-[#991b1b] to-[#fca5a5]$q$),
  ($q$arts-litterature$q$, $q$les-impressionnistes-ont-dabord-ete-moques$q$, $q$Les impressionnistes ont d’abord été moqués.$q$, $q$Un style moqué devient l’un des plus aimés.$q$, $q$Monet, Renoir ou Degas sont aujourd’hui très populaires, mais leur peinture semblait inachevée à beaucoup de critiques au XIXe siècle. Le mot “impressionnisme” vient même d’une moquerie autour d’un tableau de Monet.$q$, $q$Les impressionnistes veulent peindre la lumière, le mouvement et les sensations du moment plutôt que des scènes parfaitement lisses. Leur touche visible et leurs couleurs claires choquent une partie du public habitué à une peinture plus académique. Avec le temps, ce style devient l’un des plus appréciés au monde. Ce retournement est intéressant : ce qui paraît “mal fait” à une époque peut devenir une révolution artistique.$q$, $q$Musée d’Orsay$q$, $q$https://www.musee-orsay.fr/fr/collections/histoire-de-limpressionnisme$q$, 71, $q$#06b6d4$q$, $q$from-[#071a20] via-[#164e63] to-[#67e8f9]$q$),
  ($q$arts-litterature$q$, $q$guernica-de-picasso-repond-a-un-bombardement-reel$q$, $q$Guernica de Picasso répond à un bombardement réel.$q$, $q$Picasso transforme un drame historique en image universelle.$q$, $q$Peint en 1937, Guernica dénonce le bombardement de la ville basque de Guernica pendant la guerre d’Espagne. Le tableau devient l’une des grandes images contre la violence de guerre.$q$, $q$Picasso réalise Guernica pour le pavillon espagnol de l’Exposition internationale de Paris. Le tableau ne montre pas la scène de manière réaliste : il utilise des corps déformés, des cris et une composition chaotique pour exprimer la souffrance. C’est précisément cette force symbolique qui rend l’œuvre si célèbre. Guernica rappelle que l’art peut devenir une réponse politique à un événement historique précis.$q$, $q$Museo Reina Sofía$q$, $q$https://www.museoreinasofia.es/en/collection/artwork/guernica$q$, 72, $q$#06b6d4$q$, $q$from-[#071a20] via-[#164e63] to-[#67e8f9]$q$),
  ($q$arts-litterature$q$, $q$le-penseur-de-rodin-netait-pas-concu-comme-une-statue-isolee$q$, $q$Le Penseur de Rodin n’était pas conçu comme une statue isolée.$q$, $q$Une partie d’œuvre devient symbole de la réflexion.$q$, $q$La célèbre sculpture de Rodin faisait d’abord partie d’un ensemble plus vaste inspiré de La Divine Comédie. Avec le temps, elle devient une image universelle de l’être humain en train de penser.$q$, $q$Le Penseur est aujourd’hui souvent vu seul, comme une statue indépendante. À l’origine, il appartient pourtant au projet de La Porte de l’Enfer, une œuvre monumentale inspirée par Dante. La posture du personnage, penché en avant, donne une impression de concentration intense. Détachée de son contexte, la sculpture devient progressivement un symbole général de la réflexion, du doute et de la pensée humaine.$q$, $q$Musée Rodin$q$, $q$https://www.musee-rodin.fr/musee/collections/oeuvres/penseur$q$, 73, $q$#06b6d4$q$, $q$from-[#071a20] via-[#164e63] to-[#67e8f9]$q$),
  ($q$arts-litterature$q$, $q$shakespeare-a-marque-la-langue-anglaise$q$, $q$Shakespeare a marqué la langue anglaise.$q$, $q$Même sans le lire, on croise encore son influence.$q$, $q$William Shakespeare, dramaturge anglais des XVIe et XVIIe siècles, a écrit Hamlet, Roméo et Juliette ou Macbeth. Ses pièces ont popularisé de nombreuses expressions encore présentes dans la culture anglophone.$q$, $q$Shakespeare est souvent présenté comme l’un des plus grands auteurs de théâtre. Son importance vient autant de ses histoires que de sa langue. Il a contribué à populariser des mots, des formules et des images qui continuent de circuler. Ses personnages, comme Hamlet ou Roméo et Juliette, sont devenus des références culturelles mondiales. Même sans connaître ses textes en détail, comprendre son rôle aide à mieux situer une grande partie de la littérature occidentale.$q$, $q$Shakespeare Birthplace Trust$q$, $q$https://www.shakespeare.org.uk/explore-shakespeare/shakespedia/william-shakespeare/$q$, 74, $q$#06b6d4$q$, $q$from-[#071a20] via-[#164e63] to-[#67e8f9]$q$),
  ($q$arts-litterature$q$, $q$moliere-a-donne-son-nom-a-la-langue-francaise$q$, $q$Molière a donné son nom à la langue française.$q$, $q$Dire “la langue de Molière”, c’est parler du français.$q$, $q$Molière était un dramaturge français du XVIIe siècle, célèbre pour Le Malade imaginaire, Tartuffe ou L’Avare. Son théâtre critique les hypocrisies sociales avec humour.$q$, $q$Molière est l’une des grandes figures du théâtre français. Ses comédies ne servent pas seulement à faire rire : elles dénoncent les faux dévots, les médecins prétentieux, l’avarice ou les mariages forcés. Son influence est telle que l’on parle parfois du français comme de “la langue de Molière”. Connaître son rôle permet de comprendre une référence culturelle française très fréquente.$q$, $q$Comédie-Française$q$, $q$https://www.comedie-francaise.fr/fr/moliere$q$, 75, $q$#06b6d4$q$, $q$from-[#071a20] via-[#164e63] to-[#67e8f9]$q$),
  ($q$quotidien-societe$q$, $q$la-fourchette-a-mis-longtemps-a-simposer-en-europe$q$, $q$La fourchette a mis longtemps à s’imposer en Europe.$q$, $q$Un objet évident aujourd’hui a longtemps paru étrange.$q$, $q$Pendant des siècles, manger avec les doigts ou avec un couteau reste courant en Europe. La fourchette semble d’abord raffinée, étrangère ou inutile avant de devenir un objet de table banal.$q$, $q$Les objets du quotidien ont souvent une histoire sociale. La fourchette, aujourd’hui indispensable, ne s’impose pas partout immédiatement. Dans certaines régions, elle est perçue comme un luxe ou une bizarrerie. Les usages de table évoluent avec les cours royales, les normes de politesse et les habitudes alimentaires. Ce fait rappelle que même les gestes les plus ordinaires, comme manger avec une fourchette, sont le résultat d’une longue évolution culturelle.$q$, $q$Victoria and Albert Museum$q$, $q$https://www.vam.ac.uk/articles/a-history-of-cutlery$q$, 76, $q$#f59e0b$q$, $q$from-[#1c1608] via-[#92400e] to-[#fbbf24]$q$),
  ($q$quotidien-societe$q$, $q$le-ketchup-a-deja-ete-vendu-comme-medicament$q$, $q$Le ketchup a déjà été vendu comme médicament.$q$, $q$Une sauce de fast-food a déjà eu une image médicale.$q$, $q$Au XIXe siècle, certaines préparations à base de tomate sont présentées comme bonnes pour la digestion. Difficile à imaginer aujourd’hui, quand le ketchup évoque surtout les frites et les burgers.$q$, $q$Le ketchup n’a pas toujours eu l’image qu’on lui connaît. Son histoire passe par plusieurs recettes, parfois très différentes de la sauce tomate sucrée moderne. Au XIXe siècle, des produits à base de tomate sont associés à des vertus digestives, et certains sont vendus sous forme de remèdes. Ce fait fonctionne bien car il inverse notre perception d’un produit très banal : ce qui est aujourd’hui une sauce industrielle a parfois été présenté comme bénéfique pour la santé.$q$, $q$Smithsonian Magazine$q$, $q$https://www.smithsonianmag.com/arts-culture/ketchup-medicine-180967568/$q$, 77, $q$#f59e0b$q$, $q$from-[#1c1608] via-[#92400e] to-[#fbbf24]$q$),
  ($q$quotidien-societe$q$, $q$les-carottes-nont-pas-toujours-ete-orange$q$, $q$Les carottes n’ont pas toujours été orange.$q$, $q$L’orange n’a pas toujours été la couleur évidente des carottes.$q$, $q$Des carottes violettes, jaunes ou blanches existaient déjà depuis longtemps. La carotte orange s’impose progressivement en Europe grâce aux sélections agricoles.$q$, $q$On associe spontanément la carotte à l’orange, mais ce n’est pas une règle naturelle unique. Les variétés anciennes peuvent avoir plusieurs couleurs. Les agriculteurs sélectionnent progressivement certaines caractéristiques : goût, taille, résistance, couleur. La carotte orange devient dominante dans de nombreux pays européens. Ce fait est intéressant parce qu’il montre que même l’apparence d’un légume très courant est en partie le résultat de choix humains.$q$, $q$World Carrot Museum$q$, $q$https://www.carrotmuseum.co.uk/history.html$q$, 78, $q$#f59e0b$q$, $q$from-[#1c1608] via-[#92400e] to-[#fbbf24]$q$),
  ($q$quotidien-societe$q$, $q$le-cafe-a-longtemps-ete-suspect-dans-certains-pays$q$, $q$Le café a longtemps été suspect dans certains pays.$q$, $q$Les cafés pouvaient devenir des lieux de débat politique.$q$, $q$Parce qu’il garde les gens éveillés et rassemble des discussions, le café a parfois inquiété les autorités. Une simple boisson pouvait favoriser les échanges d’idées et les contestations.$q$, $q$Le café ne change pas seulement les habitudes alimentaires : il transforme aussi les lieux de sociabilité. Les cafés deviennent des espaces où l’on parle, lit, débat et critique parfois le pouvoir. Dans plusieurs pays, ces lieux attirent la méfiance des autorités. Ce fait est intéressant parce qu’il montre qu’un produit du quotidien peut avoir une dimension politique. Boire un café, dans certains contextes historiques, ce n’était pas seulement consommer une boisson.$q$, $q$Encyclopaedia Britannica$q$, $q$https://www.britannica.com/topic/coffee$q$, 79, $q$#f59e0b$q$, $q$from-[#1c1608] via-[#92400e] to-[#fbbf24]$q$),
  ($q$quotidien-societe$q$, $q$les-feux-rouges-reprennent-un-code-venu-du-rail$q$, $q$Les feux rouges reprennent un code venu du rail.$q$, $q$La route a hérité de signaux pensés pour les trains.$q$, $q$Avant d’organiser la circulation automobile, les couleurs rouge et verte servaient déjà à guider les trains. Le code a ensuite été adapté aux villes et aux voitures.$q$, $q$Les feux de circulation semblent évidents aujourd’hui, mais leur logique vient d’un autre monde : le chemin de fer. Les trains avaient besoin de signaux simples, visibles et compréhensibles rapidement. Le rouge s’impose comme couleur d’arrêt, le vert comme autorisation de passage. Avec l’essor de l’automobile, les villes reprennent et adaptent ce système. Ce fait montre comment une invention pensée pour un domaine peut structurer ensuite une autre partie de la vie quotidienne.$q$, $q$Smithsonian Magazine$q$, $q$https://www.smithsonianmag.com/innovation/history-of-the-traffic-light-180982902/$q$, 80, $q$#f59e0b$q$, $q$from-[#1c1608] via-[#92400e] to-[#fbbf24]$q$),
  ($q$mots-origines$q$, $q$le-mot-musee-vient-des-muses$q$, $q$Le mot musée vient des Muses de la mythologie grecque.$q$, $q$Le musée garde l’idée d’un lieu dédié aux arts et au savoir.$q$, $q$Les Muses étaient associées à la poésie, aux arts et à la connaissance. Le mot musée a fini par désigner un lieu où l’on conserve et transmet la culture.$q$, $q$Dans la mythologie grecque, les Muses inspirent les artistes, les poètes et les savants. Le mot “musée” garde cette origine culturelle : un endroit lié à la création et au savoir. Aujourd’hui, un musée peut exposer de l’art, des objets historiques, des sciences ou des civilisations. Ce fait aide à comprendre que le musée n’est pas seulement un bâtiment rempli d’objets, mais un héritier d’une longue idée : préserver et partager la mémoire humaine.$q$, $q$CNRTL$q$, $q$https://www.cnrtl.fr/definition/mus%C3%A9e$q$, 81, $q$#14b8a6$q$, $q$from-[#06221f] via-[#0f766e] to-[#5eead4]$q$),
  ($q$mots-origines$q$, $q$le-mot-algorithme-vient-du-nom-dun-savant$q$, $q$Le mot algorithme vient du nom d’un savant.$q$, $q$Un savant médiéval se cache derrière nos algorithmes.$q$, $q$Le mot vient d’Al-Khwârizmî, mathématicien persan du IXe siècle. Son nom a progressivement donné “algorithme”, un mot devenu central dans l’informatique moderne.$q$, $q$Al-Khwârizmî travaille sur les mathématiques dans le monde savant islamique médiéval. Son nom latinisé influence le mot “algorithme”. À l’origine, il ne s’agit pas d’Internet ou d’intelligence artificielle, mais de méthodes de calcul. Aujourd’hui, les algorithmes organisent les moteurs de recherche, les recommandations, les réseaux sociaux et une grande partie du numérique. Ce mot moderne garde donc une racine très ancienne.$q$, $q$Encyclopaedia Britannica$q$, $q$https://www.britannica.com/biography/al-Khwarizmi$q$, 82, $q$#14b8a6$q$, $q$from-[#06221f] via-[#0f766e] to-[#5eead4]$q$),
  ($q$mots-origines$q$, $q$le-mot-avatar-vient-du-sanskrit$q$, $q$Le mot avatar vient du sanskrit.$q$, $q$Un mot numérique existait bien avant Internet.$q$, $q$À l’origine, dans la tradition hindoue, un avatar désigne la descente d’une divinité sur terre. Aujourd’hui, le mot sert souvent à parler de notre représentation dans un monde virtuel.$q$, $q$Le mot avatar n’est pas né avec les jeux vidéo ou les réseaux sociaux. Il vient du sanskrit et appartient d’abord au vocabulaire religieux hindou. Il désigne une manifestation terrestre d’une divinité, notamment Vishnou. Le numérique a repris le mot pour désigner une version représentée de soi dans un espace virtuel. C’est un bel exemple de déplacement culturel : un terme spirituel ancien devient un mot courant de la vie en ligne.$q$, $q$Encyclopaedia Britannica$q$, $q$https://www.britannica.com/topic/avatar-Hinduism$q$, 83, $q$#14b8a6$q$, $q$from-[#06221f] via-[#0f766e] to-[#5eead4]$q$),
  ($q$geographie-monde$q$, $q$le-nil-a-rendu-legypte-antique-possible$q$, $q$Le Nil a rendu l’Égypte antique possible.$q$, $q$Sans les crues du Nil, l’Égypte n’aurait pas eu la même histoire.$q$, $q$Le Nil apportait de l’eau et des terres fertiles au milieu d’un environnement très aride. Ses crues ont permis l’agriculture, donc la stabilité nécessaire au développement de l’Égypte antique.$q$, $q$L’Égypte antique se développe autour du Nil parce que le fleuve fournit une ressource vitale : l’eau. Ses crues déposent du limon fertile sur les terres, ce qui permet de cultiver. Cette agriculture nourrit une population importante et soutient l’administration, les villes, les temples et les grands chantiers. Le Nil sert aussi de voie de transport. Comprendre ce fleuve, c’est comprendre pourquoi une grande civilisation a pu se développer dans une région entourée de désert.$q$, $q$Encyclopaedia Britannica$q$, $q$https://www.britannica.com/place/Nile-River$q$, 84, $q$#84cc16$q$, $q$from-[#101a08] via-[#3f6212] to-[#bef264]$q$),
  ($q$geographie-monde$q$, $q$le-sahara-nest-pas-seulement-du-sable$q$, $q$Le Sahara n’est pas seulement du sable.$q$, $q$Le plus célèbre des déserts est plus varié qu’on l’imagine.$q$, $q$On imagine souvent le Sahara comme une mer de dunes. Il contient pourtant aussi des plateaux rocheux, des montagnes, des plaines et des zones très différentes les unes des autres.$q$, $q$Le Sahara est le plus grand désert chaud du monde, mais il ne ressemble pas partout à une carte postale de dunes. Une grande partie de sa surface est rocheuse ou caillouteuse. On y trouve aussi des massifs montagneux, des oasis et des paysages très variés. Ce fait corrige une image simplifiée : un désert n’est pas un décor uniforme, mais un ensemble complexe de milieux adaptés à une très forte aridité.$q$, $q$National Geographic$q$, $q$https://education.nationalgeographic.org/resource/sahara-desert/$q$, 85, $q$#84cc16$q$, $q$from-[#101a08] via-[#3f6212] to-[#bef264]$q$),
  ($q$geographie-monde$q$, $q$le-canada-possede-une-quantite-immense-de-lacs$q$, $q$Le Canada possède une quantité immense de lacs.$q$, $q$Les glaciers ont laissé au Canada d’innombrables lacs.$q$, $q$Une grande partie du territoire canadien a été façonnée par les glaciers. En se retirant, ils ont creusé et rempli d’eau une quantité énorme de bassins naturels.$q$, $q$Le Canada est souvent associé aux forêts, au froid et aux grands espaces, mais ses lacs sont l’un de ses traits géographiques majeurs. Pendant les périodes glaciaires, d’immenses masses de glace ont remodelé le relief. En fondant, elles ont laissé derrière elles des cuvettes, des vallées et des bassins remplis d’eau. C’est ce passé glaciaire qui explique la présence de tant de lacs, parfois dans des régions très peu peuplées.$q$, $q$The Canadian Encyclopedia$q$, $q$https://www.thecanadianencyclopedia.ca/en/article/lake$q$, 86, $q$#84cc16$q$, $q$from-[#101a08] via-[#3f6212] to-[#bef264]$q$),
  ($q$musique-culture$q$, $q$michael-jackson-a-transforme-le-clip-musical-en-evenement$q$, $q$Michael Jackson a transformé le clip musical en événement.$q$, $q$Après Thriller, un clip pouvait devenir un mini-film mondial.$q$, $q$Avec Thriller en 1983, Michael Jackson donne au clip une ambition nouvelle : scénario, chorégraphie, maquillage, effets spéciaux. L’image devient presque aussi importante que la chanson.$q$, $q$Avant les années 1980, les clips servent surtout à promouvoir un morceau. Thriller change d’échelle. Réalisé comme un court-métrage, il raconte une histoire et devient un événement télévisuel. Michael Jackson impose aussi l’idée que la danse, le costume et la mise en scène font partie de l’identité d’un artiste pop. Après lui, le clip devient un outil majeur de la culture musicale mondiale.$q$, $q$Rock & Roll Hall of Fame$q$, $q$https://rockhall.com/inductees/michael-jackson/$q$, 87, $q$#ef4444$q$, $q$from-[#220b0b] via-[#991b1b] to-[#fca5a5]$q$),
  ($q$musique-culture$q$, $q$edith-piaf-reste-une-voix-majeure-de-la-chanson-francaise$q$, $q$Édith Piaf reste une voix majeure de la chanson française.$q$, $q$Piaf donne l’impression de raconter une vie entière en une chanson.$q$, $q$Chanteuse française du XXe siècle, Édith Piaf est connue pour La Vie en rose, Non, je ne regrette rien ou L’Hymne à l’amour. Sa voix dramatique a marqué la chanson française bien au-delà de la France.$q$, $q$Édith Piaf vient d’un milieu populaire et construit une carrière immense grâce à une voix immédiatement reconnaissable. Ses chansons parlent souvent d’amour, de perte, de courage et de destin. Elle ne chante pas seulement des mélodies : elle donne l’impression d’interpréter une histoire vécue. C’est ce mélange de fragilité et d’intensité qui explique pourquoi son nom reste une référence incontournable de la chanson française.$q$, $q$INA$q$, $q$https://www.ina.fr/ina-eclaire-actu/edith-piaf$q$, 88, $q$#ef4444$q$, $q$from-[#220b0b] via-[#991b1b] to-[#fca5a5]$q$),
  ($q$musique-culture$q$, $q$le-rocknroll-a-dabord-choque-une-partie-des-adultes$q$, $q$Le rock’n’roll a d’abord choqué une partie des adultes.$q$, $q$Le rock devient classique après avoir été provocateur.$q$, $q$Dans les années 1950, ses rythmes, ses danses et son énergie paraissent parfois menaçants pour les générations plus âgées. Ce qui semble classique aujourd’hui était alors une rupture culturelle.$q$, $q$Le rock’n’roll naît d’un mélange de rhythm and blues, de country et d’autres influences populaires américaines. Il accompagne l’essor d’une culture adolescente plus visible, avec ses idoles, ses danses et ses codes. Des artistes comme Elvis Presley provoquent autant d’enthousiasme que d’inquiétude. Avec le temps, cette musique autrefois jugée dangereuse devient une référence patrimoniale. C’est un bon exemple de révolte culturelle devenue classique.$q$, $q$Rock & Roll Hall of Fame$q$, $q$https://rockhall.com/$q$, 89, $q$#ef4444$q$, $q$from-[#220b0b] via-[#991b1b] to-[#fca5a5]$q$),
  ($q$musique-culture$q$, $q$le-jazz-est-ne-dun-melange-de-cultures$q$, $q$Le jazz est né d’un mélange de cultures.$q$, $q$Le jazz repose sur le rythme, l’improvisation et le dialogue.$q$, $q$Développé notamment à La Nouvelle-Orléans, le jazz mêle des influences africaines, européennes et américaines. Il devient l’une des grandes musiques du XXe siècle.$q$, $q$Le jazz naît dans un contexte de brassage culturel, avec une forte influence des communautés afro-américaines. Il se distingue par l’improvisation : les musiciens ne se contentent pas de rejouer une partition, ils dialoguent en direct. Le jazz influencera ensuite le swing, le bebop, le rock, la soul et de nombreuses musiques modernes. Connaître le jazz, c’est comprendre une base essentielle de la culture musicale contemporaine.$q$, $q$Smithsonian Music$q$, $q$https://music.si.edu/story/jazz$q$, 90, $q$#ef4444$q$, $q$from-[#220b0b] via-[#991b1b] to-[#fca5a5]$q$),
  ($q$inventions-technologie$q$, $q$la-photographie-a-dabord-demande-de-tres-longs-temps-de-pose$q$, $q$La photographie a d’abord demandé de très longs temps de pose.$q$, $q$Les vieux portraits sont sérieux pour une raison technique.$q$, $q$Les premières photos nécessitaient plusieurs minutes d’immobilité. C’est l’une des raisons pour lesquelles les portraits anciens semblent souvent figés, raides ou très solennels.$q$, $q$Aujourd’hui, prendre une photo est instantané. Au XIXe siècle, c’est une opération lente et technique. Les personnes photographiées doivent rester immobiles longtemps pour éviter une image floue. Sourire naturellement devient difficile dans ces conditions. Le sérieux des portraits anciens n’est donc pas seulement une question de caractère ou d’époque : il vient aussi des limites techniques de la photographie. Ce fait rend les images du passé plus compréhensibles.$q$, $q$National Geographic$q$, $q$https://www.nationalgeographic.com/photography/article/photography-history$q$, 91, $q$#3b82f6$q$, $q$from-[#071426] via-[#1d4ed8] to-[#93c5fd]$q$),
  ($q$inventions-technologie$q$, $q$la-machine-a-ecrire-a-influence-nos-claviers-modernes$q$, $q$La machine à écrire a influencé nos claviers modernes.$q$, $q$Nos claviers gardent l’héritage des machines mécaniques.$q$, $q$La disposition QWERTY vient d’une époque où les touches des machines à écrire pouvaient se bloquer. Même si les ordinateurs n’ont plus ce problème, l’habitude est restée.$q$, $q$Les claviers modernes sont les héritiers directs des machines à écrire. Sur ces machines, certaines combinaisons de touches pouvaient provoquer des blocages mécaniques. La disposition QWERTY s’impose progressivement et reste utilisée même après la disparition du problème d’origine. Ce fait montre que les technologies gardent souvent des traces du passé. Une contrainte mécanique du XIXe siècle influence encore la manière dont on tape sur ordinateur ou téléphone.$q$, $q$Computer History Museum$q$, $q$https://www.computerhistory.org/revolution/input-output/14/350$q$, 92, $q$#3b82f6$q$, $q$from-[#071426] via-[#1d4ed8] to-[#93c5fd]$q$),
  ($q$inventions-technologie$q$, $q$la-souris-dordinateur-a-ete-presentee-des-les-annees-1960$q$, $q$La souris d’ordinateur a été présentée dès les années 1960.$q$, $q$Avant d’être évidente, la souris semblait futuriste.$q$, $q$Douglas Engelbart présente la souris lors d’une démonstration célèbre en 1968. À l’époque, contrôler un ordinateur avec un petit objet posé sur une table paraît très nouveau.$q$, $q$La souris d’ordinateur est montrée lors de ce qu’on appelle parfois “la mère de toutes les démos”. Engelbart y présente aussi des idées très en avance : fenêtres, hypertexte, collaboration à distance. La souris n’est alors qu’un élément d’une vision plus large de l’informatique interactive. Aujourd’hui, elle semble banale, mais elle a transformé notre relation aux machines en rendant l’ordinateur plus visuel et plus accessible.$q$, $q$Computer History Museum$q$, $q$https://computerhistory.org/blog/the-mother-of-all-demos/$q$, 93, $q$#3b82f6$q$, $q$from-[#071426] via-[#1d4ed8] to-[#93c5fd]$q$),
  ($q$histoire-essentielle$q$, $q$le-debarquement-de-normandie-a-eu-lieu-le-6-juin-1944$q$, $q$Le débarquement de Normandie a eu lieu le 6 juin 1944.$q$, $q$Le D-Day ouvre la libération de l’Europe de l’Ouest.$q$, $q$Des milliers de soldats alliés débarquent sur les plages normandes pour ouvrir un nouveau front contre l’Allemagne nazie. L’opération devient l’un des tournants majeurs de la Seconde Guerre mondiale.$q$, $q$Le 6 juin 1944, les Alliés lancent l’opération Overlord. Des troupes américaines, britanniques, canadiennes et d’autres pays débarquent sur plusieurs plages de Normandie. L’objectif est de reprendre pied en Europe occidentale et de repousser l’armée allemande. Le débarquement est extrêmement risqué et coûteux humainement, mais il ouvre la voie à la libération de la France puis à la défaite du régime nazi en Europe. C’est une date fondamentale de la mémoire de la Seconde Guerre mondiale.$q$, $q$Imperial War Museums$q$, $q$https://www.iwm.org.uk/history/the-10-things-you-need-to-know-about-d-day$q$, 94, $q$#f97316$q$, $q$from-[#1c1917] via-[#7c2d12] to-[#fb923c]$q$),
  ($q$histoire-essentielle$q$, $q$la-seconde-guerre-mondiale-se-termine-en-1945$q$, $q$La Seconde Guerre mondiale se termine en 1945.$q$, $q$1945 marque la fin du conflit le plus meurtrier du XXe siècle.$q$, $q$La capitulation de l’Allemagne puis celle du Japon mettent fin à six années de guerre mondiale. Cette date reste essentielle pour comprendre l’ONU, l’Europe d’après-guerre et le monde contemporain.$q$, $q$La Seconde Guerre mondiale commence en 1939 en Europe et s’étend rapidement à une grande partie du monde. Elle provoque des destructions massives, la Shoah, des bombardements de villes et l’usage de l’arme nucléaire contre le Japon. En 1945, la guerre se termine, mais ses conséquences structurent durablement la planète : création de l’ONU, division de l’Europe, début de la guerre froide, reconstruction et décolonisations. C’est l’un des grands repères de l’histoire moderne.$q$, $q$Encyclopaedia Britannica$q$, $q$https://www.britannica.com/event/World-War-II$q$, 95, $q$#f97316$q$, $q$from-[#1c1917] via-[#7c2d12] to-[#fb923c]$q$),
  ($q$grandes-figures$q$, $q$ada-lovelace-est-souvent-presentee-comme-la-premiere-programmeuse$q$, $q$Ada Lovelace est souvent présentée comme la première programmeuse.$q$, $q$Une femme imagine déjà ce qu’une machine pourrait calculer.$q$, $q$Mathématicienne britannique du XIXe siècle, Ada Lovelace travaille sur la machine analytique de Charles Babbage. Elle comprend que cette machine pourrait manipuler plus que de simples nombres.$q$, $q$Ada Lovelace vit à une époque où les ordinateurs n’existent pas encore. En étudiant les idées de Charles Babbage, elle imagine qu’une machine pourrait suivre des instructions complexes. Ses notes contiennent ce qui est souvent présenté comme le premier programme destiné à une machine. Son importance vient aussi de son intuition : elle voit que le calcul mécanique pourrait ouvrir un nouveau monde intellectuel. C’est pourquoi son nom revient souvent dans l’histoire de l’informatique.$q$, $q$Computer History Museum$q$, $q$https://www.computerhistory.org/babbage/adalovelace/$q$, 96, $q$#8b5cf6$q$, $q$from-[#17132a] via-[#4c1d95] to-[#a78bfa]$q$),
  ($q$grandes-figures$q$, $q$charles-darwin-a-change-notre-maniere-de-voir-le-vivant$q$, $q$Charles Darwin a changé notre manière de voir le vivant.$q$, $q$Darwin rend l’évolution impossible à ignorer.$q$, $q$Naturaliste britannique du XIXe siècle, Darwin propose la théorie de l’évolution par sélection naturelle. Elle explique comment les espèces changent progressivement au fil du temps.$q$, $q$Darwin publie L’Origine des espèces en 1859. Son idée centrale est simple mais puissante : les individus les mieux adaptés à leur environnement ont plus de chances de survivre et de transmettre leurs traits. Sur de longues périodes, cela transforme les espèces. Cette théorie bouleverse la biologie, mais aussi la manière dont les humains se pensent dans le vivant. Darwin reste une figure essentielle pour comprendre la science moderne.$q$, $q$Natural History Museum$q$, $q$https://www.nhm.ac.uk/discover/charles-darwin-most-famous-biologist.html$q$, 97, $q$#8b5cf6$q$, $q$from-[#17132a] via-[#4c1d95] to-[#a78bfa]$q$),
  ($q$arts-litterature$q$, $q$notre-dame-de-paris-a-aide-a-sauver-la-cathedrale$q$, $q$Notre-Dame de Paris a aidé à sauver la cathédrale.$q$, $q$Un roman peut changer le regard sur un monument.$q$, $q$Le roman de Victor Hugo, publié en 1831, ravive l’intérêt pour une cathédrale alors abîmée et parfois négligée. La fiction participe à la redécouverte d’un patrimoine réel.$q$, $q$Au début du XIXe siècle, Notre-Dame de Paris n’a pas encore le statut patrimonial qu’on lui connaît aujourd’hui. Victor Hugo utilise son roman pour attirer l’attention sur la valeur des monuments médiévaux. Le succès du livre contribue à sensibiliser le public à la nécessité de restaurer la cathédrale. Ce fait montre que la littérature peut avoir des effets très concrets sur le monde réel : elle peut sauver une mémoire, un lieu, une architecture.$q$, $q$Bibliothèque nationale de France$q$, $q$https://gallica.bnf.fr/essentiels/hugo/notre-dame-paris$q$, 98, $q$#06b6d4$q$, $q$from-[#071a20] via-[#164e63] to-[#67e8f9]$q$),
  ($q$geographie-monde$q$, $q$le-canal-de-suez-raccourcit-le-trajet-entre-leurope-et-lasie$q$, $q$Le canal de Suez raccourcit le trajet entre l’Europe et l’Asie.$q$, $q$Un canal change les routes du commerce mondial.$q$, $q$Ouvert en 1869, le canal de Suez permet aux navires de passer de la Méditerranée à la mer Rouge sans contourner toute l’Afrique. Il devient rapidement un passage stratégique majeur.$q$, $q$Avant le canal de Suez, les navires reliant l’Europe à l’Asie doivent contourner l’Afrique par le cap de Bonne-Espérance. Le canal réduit fortement les distances et les temps de trajet. Il devient donc essentiel pour le commerce, le pétrole, les marchandises et les équilibres géopolitiques. Sa position explique aussi pourquoi il a été au cœur de tensions internationales. C’est un exemple très clair de géographie qui transforme l’économie mondiale.$q$, $q$Suez Canal Authority$q$, $q$https://www.suezcanal.gov.eg/English/About/SuezCanal/Pages/CanalHistory.aspx$q$, 99, $q$#84cc16$q$, $q$from-[#101a08] via-[#3f6212] to-[#bef264]$q$),
  ($q$histoire-essentielle$q$, $q$le-code-civil-de-napoleon-influence-encore-le-droit$q$, $q$Le Code civil de Napoléon influence encore le droit.$q$, $q$Un texte de 1804 structure encore la vie quotidienne.$q$, $q$Le Code civil organise des règles sur la famille, la propriété, les contrats et la responsabilité. Il montre que Napoléon n’a pas seulement marqué l’histoire par ses guerres.$q$, $q$Promulgué en 1804, le Code civil rassemble et clarifie une partie importante du droit français. Il fixe des règles communes après les bouleversements de la Révolution. Son influence dépasse la France : plusieurs pays s’en inspirent directement ou indirectement. Ce fait est important car il nuance l’image de Napoléon. Derrière le chef militaire, il y a aussi un héritage administratif et juridique encore visible aujourd’hui.$q$, $q$Vie publique$q$, $q$https://www.vie-publique.fr/fiches/19567-quest-ce-que-le-code-civil$q$, 100, $q$#f97316$q$, $q$from-[#1c1917] via-[#7c2d12] to-[#fb923c]$q$)
)
INSERT INTO public.facts (
  category_id,
  slug,
  title,
  hook,
  content,
  long_content,
  source,
  source_url,
  status,
  published_at,
  display_order,
  accent_color,
  tone,
  created_at,
  updated_at
)
SELECT
  c.id,
  fs.slug,
  fs.title,
  fs.hook,
  fs.content,
  fs.long_content,
  fs.source,
  fs.source_url,
  'published',
  COALESCE(existing.published_at, now()),
  fs.display_order,
  fs.accent_color,
  fs.tone,
  COALESCE(existing.created_at, now()),
  now()
FROM fact_seed fs
JOIN public.categories c
  ON c.slug = fs.category_slug
LEFT JOIN public.facts existing
  ON existing.slug = fs.slug
ON CONFLICT (slug) DO UPDATE SET
  category_id = EXCLUDED.category_id,
  title = EXCLUDED.title,
  hook = EXCLUDED.hook,
  content = EXCLUDED.content,
  long_content = EXCLUDED.long_content,
  source = EXCLUDED.source,
  source_url = EXCLUDED.source_url,
  status = EXCLUDED.status,
  published_at = COALESCE(public.facts.published_at, EXCLUDED.published_at),
  display_order = EXCLUDED.display_order,
  accent_color = EXCLUDED.accent_color,
  tone = EXCLUDED.tone,
  updated_at = now();

COMMIT;
